          <footer className="bg-[#f0f0f0] p-3 flex items-center space-x-3 z-30 shadow-[0_-2px_10px_rgba(0,0,0,0.05)]">
            <div className="flex-1 bg-white rounded-full px-5 py-3 shadow-sm flex items-center space-x-3 border border-gray-200">
              <span className="text-xl">😊</span>
              <div className="flex-1 devanagari text-[15px] font-medium truncate">
                {isRecording ? <span className="text-red-500 animate-pulse font-bold">सुन रही हूँ...</span> : <span className="text-gray-400">माइक दबाकर बात करें</span>}
              </div>
              <svg className="w-6 h-6 text-gray-400 rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
            </div>

            <button
              onClick={toggleRecording}
              className={`w-14 h-14 rounded-full flex items-center justify-center text-white shadow-xl transition-all active:scale-90 ${isRecording ? 'mic-active bg-red-600' : 'bg-[#128c7e] hover:bg-[#075e54]'}`}
            >
              {isRecording ? (
                <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" /></svg>
              ) : (
                <svg className="w-7 h-7" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
              )}
            </button>
          </footer>
        </div>
      )}

      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 backdrop-blur-md z-50 flex flex-col items-center justify-center space-y-6">
          <div className="w-16 h-16 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <div className="text-center">
            <h2 className="devanagari text-[#128c7e] text-2xl font-black mb-2">सहेली आ रही है...</h2>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Connecting Consultant</p>
          </div>
        </div>
      )}

      {error && (
        <div className="absolute top-24 left-6 right-6 bg-red-600 text-white p-4 rounded-2xl text-sm devanagari text-center shadow-2xl z-50">
          {error}
          <button onClick={() => setError(null)} className="block w-full mt-3 font-black underline uppercase text-[10px] tracking-widest opacity-80">Close</button>
        </div>
      )}

      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }

        @keyframes float {
          0% { transform: translateY(0px); }
          50% { transform: translateY(-15px); }
          100% { transform: translateY(0px); }
        }
        .animate-float { animation: float 5s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आपका नाम "उद्योग सहेली" है। आप ग्रामीण महिला उद्यमियों की सच्ची सलाहकार और बिज़नेस पार्टनर हैं।

भाषा और व्यवहार नियम:
1. **सिर्फ हिंदी (देवनागरी)**: आपका हर शब्द केवल शुद्ध हिंदी और देवनागरी लिपि में होना चाहिए। अंग्रेजी या रोमन लिपि का प्रयोग बिल्कुल न करें।
2. **आत्मीयता**: यूज़र को "दीदी" या "बहन" कहकर संबोधित करें। आपकी आवाज़ में अपनापन और हौसला होना चाहिए।
3. **सरलता**: बिज़नेस के कठिन शब्दों को सरल भाषा में समझाएं। 

बातचीत का तरीका:
- सबसे पहले यूज़र का स्वागत करें और उनके बिज़नेस के बारे में पूछें।
- सलाह देने से पहले उनके बजट, इलाके और बाज़ार की जानकारी लें।
- अगर कोई सरकारी योजना की बात हो, तो 'search_grounding' का उपयोग करें।
- अगर पैकेजिंग या विज्ञापन दिखाना हो, तो 'generate_image' का उपयोग करें।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";

const searchGroundingTool: FunctionDeclaration = {
  name: 'search_grounding',
  parameters: {
    type: Type.OBJECT,
    properties: {
      query: { type: Type.STRING, description: 'सर्च करने के लिए सवाल' },
      title: { type: Type.STRING, description: 'जानकारी का शीर्षक' }
    },
    required: ['query', 'title']
  }
};

const generateImageTool: FunctionDeclaration = {
  name: 'generate_image',
  parameters: {
    type: Type.OBJECT,
    properties: {
      prompt: { type: Type.STRING, description: 'चित्र का विवरण' },
      isEditing: { type: Type.BOOLEAN, description: 'बदलाव करना है?' },
      title: { type: Type.STRING, description: 'चित्र का नाम' }
    },
    required: ['prompt', 'title']
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'DASHBOARD' | 'CHAT'>('WELCOME');
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');
  const currentToolVisual = useRef<VisualContent | null>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    if (view === 'CHAT') scrollToBottom();
  }, [messages, status, view]);

  const stopAudio = () => {
    sourcesRef.current.forEach(s => {
      try { s.stop(); s.disconnect(); } catch (e) {}
    });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const playTone = (type: 'start' | 'stop' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'start') {
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now); osc.stop(now + 0.15);
    } else if (type === 'message') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(660, now);
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    }
  };

  const handleBackToDashboard = () => {
    if (sessionRef.current) {
      try { sessionRef.current.close(); } catch (e) {}
      sessionRef.current = null;
    }
    stopAudio();
    setView('DASHBOARD');
    setMessages([]);
    setSelectedTopic(null);
    setStatus(AppStatus.IDLE);
    if (isRecording) stopRecordingInternal();
  };

  const handleSelectTopic = (topic: typeof TOPICS[0]) => {
    setSelectedTopic(topic);
    setView('CHAT');
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) {
      micProcessorRef.current.disconnect();
      micProcessorRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    setIsRecording(false);
  };

  const initSession = async (topic: typeof TOPICS[0]) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + `\nमुख्य विषय: ${topic.name}`,
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        tools: [{ functionDeclarations: [searchGroundingTool, generateImageTool] }]
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.toolCall) {
            for (const fc of message.toolCall.functionCalls) {
              if (fc.name === 'search_grounding') {
                const args = fc.args as { query: string, title: string };
                await handleSearch(args.query, args.title);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "सर्च सफल" } }]
                });
              } else if (fc.name === 'generate_image') {
                const args = fc.args as { prompt: string, title: string };
                await handleImage(args.prompt, args.title);
                sessionRef.current?.sendToolResponse({
                  functionResponses: [{ id: fc.id, name: fc.name, response: { result: "चित्र सफल" } }]
                });
              }
            }
          }

          if (message.serverContent?.inputTranscription) currentInputTranscription.current += message.serverContent.inputTranscription.text;
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;

          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText || currentToolVisual.current) {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now(), visual: currentToolVisual.current || undefined } as TranscriptionItem]);
              playTone('message');
            }
            currentInputTranscription.current = ''; currentOutputTranscription.current = ''; currentToolVisual.current = null;
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => {
              sourcesRef.current.delete(source);
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING);
            });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }

          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setError("इंटरनेट की दिक्कत है। कृपया फिर से कोशिश करें।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });

    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const handleSearch = async (query: string, title: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({ model: "gemini-3-flash-preview", contents: query, config: { tools: [{ googleSearch: {} }] } });
      const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
        uri: c.web?.uri || '', title: c.web?.title || 'जानकारी'
      })).filter((l: any) => l.uri) || [];
      currentToolVisual.current = { type: 'search', title, content: response.text, groundingLinks: links };
    } catch (e) {}
  };

  const handleImage = async (prompt: string, title: string) => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const response = await ai.models.generateContent({ model: 'gemini-2.5-flash-image', contents: [{ text: prompt }] });
      const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (part?.inlineData) {
        currentToolVisual.current = { type: 'image', title, url: `data:image/png;base64,${part.inlineData.data}`, content: response.text };
      }
    } catch (e) {}
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      if (!selectedTopic) return;
      stopAudio();
      const session = await initSession(selectedTopic);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => {
        session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
      };
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
      playTone('start');
    } else {
      stopRecordingInternal();
    }
  };

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-8 max-w-sm w-full">
            <div className="relative w-full h-80 animate-float flex items-center justify-center">
                <div className="absolute inset-0 bg-green-100/40 rounded-[60px] blur-3xl scale-90"></div>
                <img src={SAHELI_IMAGE} alt="Logo" className="relative z-10 w-full h-full object-contain rounded-3xl shadow-2xl" />
            </div>
            <div className="space-y-3">
              <h1 className="text-4xl font-black text-green-900 devanagari tracking-tight">उद्योग सहेली</h1>
              <p className="text-xl text-green-700 font-bold devanagari">आपकी बिज़नेस पार्टनर</p>
              <div className="bg-white/80 backdrop-blur-sm p-5 rounded-3xl border border-green-100 shadow-sm text-left space-y-3">
                <p className="text-sm text-slate-700 devanagari">● बैंक लोन और सरकारी योजनाओं की मदद।</p>
                <p className="text-sm text-slate-700 devanagari">● सामान बेचने के नए तरीके और मार्केटिंग।</p>
                <p className="text-sm text-slate-700 devanagari">● बस बोलकर अपना सवाल पूछें।</p>
              </div>
            </div>
          </div>
          <button onClick={() => setView('DASHBOARD')} className="w-full max-w-xs bg-[#128c7e] text-white py-4 rounded-2xl font-bold text-xl devanagari shadow-xl flex items-center justify-center space-x-3 transition-transform active:scale-95">
            <span>नमस्ते, शुरू करें</span>
          </button>
          <p className="mt-4 text-[10px] text-slate-400 font-bold">डिजिटल ग्रामीण उद्यमिता पहल</p>
        </div>
      ) : view === 'DASHBOARD' ? (
        <>
          <header className="bg-[#128c7e] text-white px-4 py-4 flex flex-col shadow-lg z-20">
            <h1 className="text-xl font-bold devanagari">उद्योग सहेली</h1>
            <div className="flex justify-around mt-4 text-[11px] font-bold uppercase tracking-widest border-b border-white/20 pb-2">
              <span className="opacity-60">चैट</span>
              <span className="border-b-2 border-white pb-2 px-4">विषय</span>
              <span className="opacity-60">प्रोफ़ाइल</span>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto bg-white">
            <div className="p-4 bg-green-50 flex items-center space-x-4 border-b border-gray-100">
              <img src={SAHELI_IMAGE} className="w-12 h-12 rounded-full object-cover border-2 border-white" alt="Avatar" />
              <div>
                 <h3 className="font-bold devanagari text-green-900 text-lg">आपकी बिज़नेस सहेली</h3>
                 <p className="text-[10px] text-green-700 font-bold uppercase">मदद के लिए तैयार</p>
              </div>
            </div>
            <div className="divide-y divide-gray-100">
              {TOPICS.map((topic) => (
                <button key={topic.id} onClick={() => handleSelectTopic(topic)} className="w-full flex items-center p-5 hover:bg-gray-50 active:bg-gray-100 text-left">
                  <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center text-2xl shadow-inner">{topic.icon}</div>
                  <div className="ml-4 flex-1">
                    <h4 className="font-bold text-[17px] devanagari text-slate-800">{topic.name}</h4>
                    <p className="text-[13px] text-gray-500 devanagari truncate">{topic.desc}</p>
                  </div>
                </button>
              ))}
            </div>
          </main>
        </>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white px-4 py-3 flex items-center shadow-lg z-20">
            <button onClick={handleBackToDashboard} className="p-1 mr-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg></button>
            <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20" alt="Chat" />
            <div className="ml-3">
              <h1 className="text-lg font-bold devanagari leading-none">{selectedTopic?.name}</h1>
              <p className="text-[10px] opacity-90 mt-1 uppercase font-medium">{status === AppStatus.SPEAKING ? 'सहेली बोल रही है...' : status === AppStatus.LISTENING ? 'आपकी बात सुन रही हूँ...' : 'ऑनलाइन'}</p>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto p-3 space-y-4 pb-28">
            {messages.length === 0 && (
              <div className="flex justify-center items-center py-10 px-6 text-center">
                <div className="devanagari text-slate-500 text-sm bg-white/80 p-6 rounded-3xl shadow-sm">
                  <p className="font-bold text-lg text-[#128c7e] mb-2">नमस्ते दीदी! 👋</p>
                  <p>नीचे हरा बटन दबाकर बात करना शुरू करें। मुझे बताएं कि मैं आपकी क्या मदद कर सकती हूँ?</p>
                </div>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-3 rounded-xl ${m.role === 'user' ? 'bubble-user' : 'bubble-saheli'}`}>
                  {m.visual && (
                    <div className="mb-2 rounded-lg overflow-hidden border border-gray-100">
                      {m.visual.url && <img src={m.visual.url} className="w-full h-auto object-cover max-h-60" alt="visual" />}
                      <div className="p-3 bg-gray-50">
                        <h4 className="font-bold text-sm devanagari mb-2">{m.visual.title}</h4>
                        {m.visual.groundingLinks?.map((l, j) => (
                          <a key={j} href={l.uri} target="_blank" className="block text-xs text-blue-600 bg-white p-2 mt-1 rounded border font-bold">● {l.title}</a>
                        ))}
                      </div>
                    </div>
                  )}
                  <p className="devanagari text-[17px] leading-[1.6] text-slate-800 whitespace-pre-wrap">{m.text}</p>
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>
          <footer className="bg-[#f0f0f0] p-4 flex items-center space-x-4 z-30">
            <div className="flex-1 bg-white rounded-full px-5 py-4 shadow-sm flex items-center border border-gray-200">
              <span className="devanagari text-[16px] text-gray-500 font-medium">
                {isRecording ? <span className="text-red-600 animate-pulse font-bold">मैं सुन रही हूँ, बोलिए...</span> : 'पूछने के लिए माइक दबाएं'}
              </span>
            </div>
            <button onClick={toggleRecording} className={`w-16 h-16 rounded-full flex items-center justify-center text-white shadow-xl transition-all ${isRecording ? 'mic-active' : 'bg-[#128c7e]'}`}>
              {isRecording ? <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" /></svg> : <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>}
            </button>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/90 backdrop-blur-md z-50 flex flex-col items-center justify-center">
          <div className="w-14 h-14 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <h2 className="devanagari text-[#128c7e] text-xl font-bold mt-4">सहेली कनेक्ट हो रही है...</h2>
        </div>
      )}
      {error && (
        <div className="absolute top-20 left-4 right-4 bg-red-600 text-white p-4 rounded-xl text-center devanagari z-50 shadow-2xl">
          {error}
          <button onClick={() => setError(null)} className="block w-full mt-2 font-black underline">ठीक है</button>
        </div>
      )}
    </div>
  );
};

export default App;

export enum AppStatus {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  ERROR = 'ERROR'
}

export interface GroundingLink {
  uri: string;
  title: string;
}

export interface VisualContent {
  type: 'image' | 'map' | 'search' | 'info';
  title?: string;
  url?: string;
  content?: string;
  items?: { title: string; subtitle?: string; url?: string }[];
  groundingLinks?: GroundingLink[];
  isGenerating?: boolean;
}

export interface TranscriptionItem {
  text: string;
  role: 'user' | 'model';
  timestamp: number;
  visual?: VisualContent;
}

export interface UserProfile {
  name: string;
  mobile: string;
  location: string;
  onboarded: boolean;
}

export interface FeedbackEntry {
  text?: string;
  audioBlob?: Blob;
  timestamp: number;
  userId: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent, UserProfile } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आपका नाम "उद्योग सहेली" है। आप ग्रामीण महिला उद्यमियों की सच्ची सलाहकार और बिज़नेस पार्टनर हैं।

भाषा और व्यवहार नियम:
1. **सिर्फ हिंदी (देवनागरी)**: आपका हर शब्द केवल शुद्ध हिंदी और देवनागरी लिपि में होना चाहिए।
2. **आत्मीयता**: यूज़र को "दीदी" या "बहन" कहकर संबोधित करें।
3. **सरलता**: बिज़नेस के कठिन शब्दों को सरल भाषा में समझाएं। 

बातचीत का तरीका:
- सबसे पहले यूज़र का स्वागत करें और उनके बिज़नेस के बारे में पूछें।
- सलाह देने से पहले उनके बजट, इलाके और बाज़ार की जानकारी लें।
- सरकारी योजनाओं के लिए 'search_grounding' और विज़ुअल्स के लिए 'generate_image' का उपयोग करें।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0);
  const [userProfile, setUserProfile] = useState<UserProfile>({ name: '', mobile: '', location: '', onboarded: false });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedbackText, setFeedbackText] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');
  const currentToolVisual = useRef<VisualContent | null>(null);

  // Load profile from local storage if exists
  useEffect(() => {
    const saved = localStorage.getItem('udyog_saheli_profile');
    if (saved) {
      setUserProfile(JSON.parse(saved));
    }
  }, []);

  const saveProfile = (data: UserProfile) => {
    localStorage.setItem('udyog_saheli_profile', JSON.stringify(data));
    setUserProfile(data);
    // In a real app, you would fetch('your-backend-api/user', { method: 'POST', body: JSON.stringify(data) })
    console.log("Saving user profile to DB:", data);
  };

  const submitFeedback = () => {
    if (!feedbackText.trim()) return;
    const feedback = { text: feedbackText, userId: userProfile.mobile, timestamp: Date.now() };
    console.log("Feedback submitted to DB:", feedback);
    // Real API call here
    alert("दीदी, आपकी प्रतिक्रिया के लिए धन्यवाद! हम जल्द ही इसे बेहतर बनाएंगे।");
    setFeedbackText('');
    setView('DASHBOARD');
  };

  const scrollToBottom = () => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  useEffect(() => { if (view === 'CHAT') scrollToBottom(); }, [messages, status, view]);

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const playTone = (type: 'start' | 'stop' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'start') {
      osc.frequency.setValueAtTime(440, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now); gain.gain.linearRampToValueAtTime(0.2, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now); osc.stop(now + 0.15);
    } else if (type === 'message') {
      osc.type = 'triangle'; osc.frequency.setValueAtTime(660, now);
      gain.gain.setValueAtTime(0, now); gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    }
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + `\nयूज़र की जानकारी: ${JSON.stringify(userProfile)}` + (customInstruction ? `\n${customInstruction}` : ""),
        outputAudioTranscription: {},
        inputAudioTranscription: {},
        tools: [{ functionDeclarations: [
          { name: 'search_grounding', parameters: { type: Type.OBJECT, properties: { query: { type: Type.STRING }, title: { type: Type.STRING } }, required: ['query', 'title'] } },
          { name: 'generate_image', parameters: { type: Type.OBJECT, properties: { prompt: { type: Type.STRING }, title: { type: Type.STRING } }, required: ['prompt', 'title'] } }
        ] }]
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.inputTranscription) {
            const text = message.serverContent.inputTranscription.text;
            if (view === 'ONBOARDING') {
              if (onboardingStep === 0) setUserProfile(p => ({ ...p, name: text }));
              else if (onboardingStep === 2) setUserProfile(p => ({ ...p, location: text }));
            }
          }
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText || currentToolVisual.current) {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now(), visual: currentToolVisual.current || undefined } as TranscriptionItem]);
              playTone('message');
            }
            currentInputTranscription.current = ''; currentOutputTranscription.current = ''; currentToolVisual.current = null;
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setError("इंटरनेट की दिक्कत है।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async (customInstruction?: string) => {
    if (!isRecording) {
      stopAudio();
      const session = await initSession(customInstruction);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
      playTone('start');
    } else {
      stopRecordingInternal();
    }
  };

  const renderOnboarding = () => {
    const steps = [
      { label: "आपका नाम क्या है?", key: 'name', type: 'text', icon: '👤' },
      { label: "आपका मोबाइल नंबर?", key: 'mobile', type: 'tel', icon: '📱' },
      { label: "आप किस शहर/राज्य से हैं?", key: 'location', type: 'text', icon: '📍' }
    ];
    const current = steps[onboardingStep];

    const next = () => {
      if (onboardingStep < steps.length - 1) setOnboardingStep(onboardingStep + 1);
      else { saveProfile({ ...userProfile, onboarded: true }); setView('DASHBOARD'); }
    };

    return (
      <div className="flex flex-col h-full bg-white p-6 animate-fade-in">
        <div className="flex justify-between items-center mb-8">
           <div className="flex space-x-2">
             {steps.map((_, i) => (
               <div key={i} className={`h-2 w-12 rounded-full ${i <= onboardingStep ? 'bg-[#128c7e]' : 'bg-gray-200'}`} />
             ))}
           </div>
           <span className="text-[10px] font-bold text-gray-400 uppercase">Step {onboardingStep + 1} of 3</span>
        </div>

        <div className="flex-1 flex flex-col justify-center space-y-8">
          <div className="flex items-center space-x-4">
            <div className="w-16 h-16 bg-green-50 rounded-full flex items-center justify-center text-3xl shadow-sm">{current.icon}</div>
            <h2 className="text-2xl font-black text-slate-800 devanagari">{current.label}</h2>
          </div>

          <div className="space-y-4">
            <input
              type={current.type}
              value={userProfile[current.key as keyof UserProfile] as string}
              onChange={(e) => setUserProfile({ ...userProfile, [current.key]: e.target.value })}
              className="w-full text-2xl font-bold p-4 border-b-4 border-[#128c7e] focus:outline-none bg-transparent devanagari"
              placeholder="यहाँ लिखें..."
              autoFocus
            />

            <button
              onMouseDown={() => toggleRecording(`यूज़र का ${current.label} पूछें।`)}
              onMouseUp={() => stopRecordingInternal()}
              className={`w-full py-4 rounded-2xl flex items-center justify-center space-x-3 transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-100 text-gray-600'}`}
            >
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
              <span className="font-bold devanagari">{isRecording ? "सुन रही हूँ..." : "बोलकर बताएं"}</span>
            </button>
          </div>
        </div>

        <button 
          onClick={next}
          disabled={!userProfile[current.key as keyof UserProfile]}
          className={`w-full py-4 rounded-2xl font-bold text-xl devanagari transition-all ${userProfile[current.key as keyof UserProfile] ? 'bg-[#128c7e] text-white shadow-lg' : 'bg-gray-200 text-gray-400'}`}
        >
          {onboardingStep === 2 ? "शुरू करें" : "अगला"}
        </button>
      </div>
    );
  };

  const renderFeedback = () => (
    <div className="flex flex-col h-full bg-white p-6 animate-fade-in">
      <header className="flex items-center justify-between mb-8">
        <button onClick={() => setView('DASHBOARD')} className="text-gray-400 hover:text-gray-600">
           <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
        <h2 className="text-xl font-bold devanagari">हमें सुझाव दें</h2>
        <div className="w-8"></div>
      </header>

      <div className="flex-1 space-y-6">
        <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100">
          <p className="text-sm text-orange-800 devanagari font-bold">दीदी, क्या आपको यह ऐप पसंद आया? हम इसे और कैसे बेहतर बना सकते हैं? कृपया हमें बताएं।</p>
        </div>

        <textarea
          value={feedbackText}
          onChange={(e) => setFeedbackText(e.target.value)}
          className="w-full h-48 p-4 rounded-2xl border-2 border-gray-100 focus:border-[#128c7e] focus:outline-none devanagari text-lg"
          placeholder="यहाँ अपना सुझाव लिखें..."
        />

        <button
          onClick={() => toggleRecording("यूज़र से फीडबैक मांगें।")}
          className={`w-full py-6 rounded-2xl flex flex-col items-center justify-center space-y-2 transition-all ${isRecording ? 'bg-red-50 text-red-600 border-2 border-red-200' : 'bg-[#128c7e]/5 text-[#128c7e] border-2 border-[#128c7e]/10'}`}
        >
          <div className={`w-12 h-12 rounded-full flex items-center justify-center ${isRecording ? 'bg-red-500' : 'bg-[#128c7e]'} text-white shadow-md`}>
             <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
          </div>
          <span className="font-bold devanagari">{isRecording ? "मैं सुन रही हूँ, बोलिये..." : "बोलकर सुझाव दें"}</span>
        </button>
      </div>

      <button
        onClick={submitFeedback}
        disabled={!feedbackText.trim()}
        className={`w-full py-4 rounded-2xl font-bold text-xl devanagari ${feedbackText.trim() ? 'bg-[#128c7e] text-white' : 'bg-gray-200 text-gray-400'}`}
      >
        सुझाव भेजें
      </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-8 max-w-sm w-full">
            <div className="relative w-full h-80 animate-float flex items-center justify-center">
                <div className="absolute inset-0 bg-green-100/40 rounded-[60px] blur-3xl scale-90"></div>
                <img src={SAHELI_IMAGE} alt="Logo" className="relative z-10 w-full h-full object-contain rounded-3xl shadow-2xl" />
            </div>
            <div className="space-y-3">
              <h1 className="text-4xl font-black text-green-900 devanagari tracking-tight">उद्योग सहेली</h1>
              <p className="text-xl text-green-700 font-bold devanagari">आपकी बिज़नेस पार्टनर</p>
            </div>
          </div>
          <button 
            onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} 
