          <main className="flex-1 overflow-y-auto bg-white">
            <div className="p-4 bg-green-50 flex items-center space-x-4 border-b border-gray-100">
              <img src={SAHELI_IMAGE} className="w-12 h-12 rounded-full object-cover border-2 border-white shadow-sm" alt="Avatar" />
              <div>
                 <h3 className="font-bold devanagari text-green-900 text-lg">आपकी बिज़नेस सहेली</h3>
                 <p className="text-[10px] text-green-700 font-bold uppercase">मदद के लिए तैयार</p>
