                  <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center text-2xl shadow-inner">{topic.icon}</div>
                  <div className="ml-4 flex-1">
                    <h4 className="font-bold text-[17px] devanagari text-slate-800">{topic.name}</h4>
                    <p className="text-[13px] text-gray-500 devanagari truncate">{topic.desc}</p>
                  </div>
                </button>
              ))}
            </div>
          </main>
        </>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white px-4 py-3 flex items-center shadow-lg z-20">
            <button onClick={() => { if(sessionRef.current) sessionRef.current.close(); sessionRef.current=null; stopAudio(); setView('DASHBOARD'); setMessages([]); setStatus(AppStatus.IDLE); }} className="p-1 mr-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg></button>
            <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20" alt="Chat" />
            <div className="ml-3">
              <h1 className="text-lg font-bold devanagari leading-none">{selectedTopic?.name}</h1>
              <p className="text-[10px] opacity-90 mt-1 uppercase font-medium">{status === AppStatus.SPEAKING ? 'सहेली बोल रही है...' : status === AppStatus.LISTENING ? 'सुन रही हूँ...' : 'ऑनलाइन'}</p>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto p-3 space-y-4 pb-28">
            {messages.map((m, i) => (
              <div key={i} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                <div className={`max-w-[85%] p-3 rounded-xl shadow-sm ${m.role === 'user' ? 'bubble-user' : 'bubble-saheli'}`}>
                  <p className="devanagari text-[17px] leading-[1.6] text-slate-800 whitespace-pre-wrap">{m.text}</p>
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>
          <footer className="bg-[#f0f0f0] p-4 flex items-center space-x-4 z-30">
            <div className="flex-1 bg-white rounded-full px-5 py-4 shadow-sm flex items-center border border-gray-200">
              <span className="devanagari text-[16px] text-gray-500 font-medium">
                {isRecording ? <span className="text-red-600 animate-pulse font-bold">मैं सुन रही हूँ, बोलिए...</span> : 'पूछने के लिए माइक दबाएं'}
              </span>
            </div>
            <button onMouseDown={() => toggleRecording(`मुख्य विषय: ${selectedTopic?.name}`)} onMouseUp={() => stopRecordingInternal()} className={`w-16 h-16 rounded-full flex items-center justify-center text-white shadow-xl transition-all ${isRecording ? 'mic-active' : 'bg-[#128c7e]'}`}>
               <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
            </button>
          </footer>
        </div>
      )}

      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/90 backdrop-blur-md z-50 flex flex-col items-center justify-center">
          <div className="w-14 h-14 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <h2 className="devanagari text-[#128c7e] text-xl font-bold mt-4">उद्योग सहेली कनेक्ट हो रही है...</h2>
        </div>
      )}

      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-10px); } }
        .animate-float { animation: float 4s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent, UserProfile } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आपका नाम "उद्योग सहेली" है। आप ग्रामीण महिला उद्यमियों की सच्ची सलाहकार हैं।

अनिवार्य नियम (Strict Rules):
1. **सिर्फ देवनागरी (Devanagari Only)**: आपका हर शब्द, हर अक्षर केवल हिंदी देवनागरी लिपि में होना चाहिए। किसी भी परिस्थिति में उर्दू, अरबी, पंजाबी या अन्य लिपियों का उपयोग न करें।
2. **नाम और जानकारी**: यदि यूज़र अपना नाम बताता है, तो उसे केवल देवनागरी लिपि में ही लिखें और बोलें। 
3. **भाषा**: सरल खड़ी बोली का प्रयोग करें। "दीदी" या "बहन" कहें।
4. **अंक**: आप अंक (1, 2, 3) या हिंदी शब्द (एक, दो, तीन) का उपयोग कर सकते हैं।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0);
  const [userProfile, setUserProfile] = useState<UserProfile>({ name: '', mobile: '', location: '', onboarded: false });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedbackText, setFeedbackText] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentInputTranscription = useRef<string>('');
  const currentOutputTranscription = useRef<string>('');

  // Initial Load
  useEffect(() => {
    const saved = localStorage.getItem('udyog_saheli_profile');
    if (saved) {
      const parsed = JSON.parse(saved);
      setUserProfile(parsed);
    }
  }, []);

  const saveProfile = (data: UserProfile) => {
    localStorage.setItem('udyog_saheli_profile', JSON.stringify(data));
    setUserProfile(data);
  };

  const handleLogout = () => {
    if (window.confirm("क्या आप वाकई लॉगआउट करना चाहती हैं? आपकी जानकारी हटा दी जाएगी।")) {
      localStorage.removeItem('udyog_saheli_profile');
      setUserProfile({ name: '', mobile: '', location: '', onboarded: false });
      setView('WELCOME');
      setOnboardingStep(0);
    }
  };

  const submitFeedback = () => {
    if (!feedbackText.trim()) {
      alert("कृपया अपना सुझाव लिखें।");
      return;
    }
    console.log("Feedback submitted:", { text: feedbackText, user: userProfile.name });
    alert("धन्यवाद दीदी! आपका सुझाव हमें मिल गया है।");
    setFeedbackText('');
    setView('DASHBOARD');
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const playTone = (type: 'start' | 'message') => {
    const ctx = audioContextRef.current?.output;
    if (!ctx) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'start') {
      osc.frequency.setValueAtTime(440, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0, now); gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.15);
      osc.start(now); osc.stop(now + 0.15);
    } else {
      osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
      gain.gain.setValueAtTime(0, now); gain.gain.linearRampToValueAtTime(0.1, now + 0.05);
      gain.gain.linearRampToValueAtTime(0, now + 0.2);
      osc.start(now); osc.stop(now + 0.2);
    }
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + (customInstruction ? `\nकार्य: ${customInstruction}` : ""),
        outputAudioTranscription: {},
        inputAudioTranscription: {},
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.inputTranscription) {
            const text = message.serverContent.inputTranscription.text;
            if (view === 'ONBOARDING') {
              if (onboardingStep === 0) setUserProfile(p => ({ ...p, name: text }));
              else if (onboardingStep === 1) setUserProfile(p => ({ ...p, mobile: text }));
              else if (onboardingStep === 2) setUserProfile(p => ({ ...p, location: text }));
            } else if (view === 'FEEDBACK') {
              setFeedbackText(prev => prev + " " + text);
            }
          }
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText && view === 'CHAT') {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now() }]);
              playTone('message');
            }
            currentInputTranscription.current = ''; currentOutputTranscription.current = '';
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setError("नेटवर्क की समस्या।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async (instr?: string) => {
    if (!isRecording) {
      stopAudio();
      const session = await initSession(instr);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
      playTone('start');
    } else {
      stopRecordingInternal();
    }
  };

  const closeSession = () => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    stopAudio();
    setStatus(AppStatus.IDLE);
  };

  const renderOnboarding = () => {
    const steps = [
      { label: "आपका शुभ नाम क्या है?", key: 'name', type: 'text', icon: '👤' },
      { label: "आपका मोबाइल नंबर क्या है?", key: 'mobile', type: 'tel', icon: '📱' },
      { label: "आप किस शहर या राज्य से हैं?", key: 'location', type: 'text', icon: '📍' }
    ];
    const current = steps[onboardingStep];

    return (
      <div className="flex flex-col h-full bg-white p-6 animate-fade-in">
        <div className="flex justify-between items-center mb-6">
           <button onClick={() => setOnboardingStep(Math.max(0, onboardingStep - 1))} className="text-gray-400">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           </button>
           <div className="flex space-x-1">
             {steps.map((_, i) => <div key={i} className={`h-1.5 w-8 rounded-full ${i <= onboardingStep ? 'bg-[#128c7e]' : 'bg-gray-100'}`} />)}
           </div>
           <div className="w-6"></div>
        </div>

        <div className="flex-1 flex flex-col justify-center space-y-8">
          <div className="text-center space-y-4">
            <div className="w-20 h-20 bg-green-50 rounded-full mx-auto flex items-center justify-center text-4xl shadow-sm border border-green-100">{current.icon}</div>
            <h2 className="text-2xl font-black text-slate-800 devanagari">{current.label}</h2>
          </div>

          <div className="space-y-6">
            <input
              type={current.type}
              value={userProfile[current.key as keyof UserProfile] as string}
              onChange={(e) => setUserProfile({ ...userProfile, [current.key]: e.target.value })}
              className="w-full text-2xl font-bold p-4 border-b-2 border-[#128c7e] focus:outline-none bg-transparent devanagari text-center"
              placeholder="यहाँ लिखें..."
            />

            <button
              onMouseDown={() => toggleRecording(`यूज़र का ${current.label} देवनागरी में लिखें।`)}
              onMouseUp={() => stopRecordingInternal()}
              className={`w-full py-5 rounded-3xl flex items-center justify-center space-x-3 transition-all ${isRecording ? 'bg-red-500 text-white shadow-lg' : 'bg-gray-50 text-gray-500'}`}
            >
              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
              <span className="font-bold devanagari">{isRecording ? "मैं सुन रही हूँ..." : "बोलकर बताएं"}</span>
            </button>
          </div>
        </div>

        <button 
          onClick={() => {
            if (onboardingStep < 2) setOnboardingStep(onboardingStep + 1);
            else { saveProfile({ ...userProfile, onboarded: true }); setView('DASHBOARD'); closeSession(); }
          }}
          disabled={!userProfile[current.key as keyof UserProfile]}
          className={`w-full py-5 rounded-3xl font-bold text-xl devanagari shadow-xl ${userProfile[current.key as keyof UserProfile] ? 'bg-[#128c7e] text-white' : 'bg-gray-200 text-gray-400'}`}
        >
          {onboardingStep === 2 ? "शुरू करें" : "अगला"}
        </button>
      </div>
    );
  };

  const renderFeedback = () => (
    <div className="flex flex-col h-full bg-white animate-fade-in">
      <header className="bg-[#128c7e] text-white p-4 flex items-center justify-between">
        <button onClick={() => setView('DASHBOARD')} className="p-2">
           <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" /></svg>
        </button>
        <h2 className="text-xl font-bold devanagari">सुझाव दें</h2>
        <button onClick={() => setView('DASHBOARD')} className="p-2">
           <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
        </button>
      </header>

      <div className="flex-1 p-6 space-y-6 overflow-y-auto">
        <div className="bg-orange-50 p-4 rounded-2xl border border-orange-200">
          <p className="text-[15px] text-orange-900 devanagari leading-relaxed">दीदी, आपको यह ऐप कैसा लगा? इसमें क्या और होना चाहिए? कृपया लिखकर या बोलकर बताएं।</p>
        </div>

        <textarea
          value={feedbackText}
          onChange={(e) => setFeedbackText(e.target.value)}
          className="w-full h-40 p-4 rounded-2xl border-2 border-gray-100 focus:border-[#128c7e] focus:outline-none devanagari text-lg shadow-inner"
          placeholder="यहाँ अपना सुझाव लिखें..."
        />

        <button
          onMouseDown={() => toggleRecording("यूज़र से फीडबैक देवनागरी में लें।")}
          onMouseUp={() => stopRecordingInternal()}
          className={`w-full py-6 rounded-3xl flex flex-col items-center justify-center space-y-2 transition-all ${isRecording ? 'bg-red-500 text-white shadow-2xl scale-105' : 'bg-gray-50 text-gray-600 border border-gray-200'}`}
        >
          <svg className={`w-8 h-8 ${isRecording ? 'text-white' : 'text-[#128c7e]'}`} fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
          <span className="font-bold devanagari text-lg">{isRecording ? "मैं सुन रही हूँ, बोलिये..." : "बोलकर सुझाव दें"}</span>
        </button>
      </div>

      <div className="p-6">
        <button
          onClick={submitFeedback}
          className="w-full py-5 rounded-3xl font-bold text-xl devanagari bg-[#128c7e] text-white shadow-xl active:scale-95 transition-transform"
        >
          सुझाव भेजें
        </button>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-8 w-full max-w-xs">
            <div className="relative w-full h-80 animate-float flex items-center justify-center">
                <div className="absolute inset-0 bg-green-100/40 rounded-[60px] blur-3xl scale-90"></div>
                <img src={SAHELI_IMAGE} alt="Logo" className="relative z-10 w-full h-full object-contain rounded-3xl shadow-2xl" />
            </div>
            <div className="space-y-2">
              <h1 className="text-4xl font-black text-green-900 devanagari">उद्योग सहेली</h1>
              <p className="text-xl text-green-700 font-bold devanagari">आपकी बिज़नेस पार्टनर</p>
            </div>
          </div>
          <button 
            onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} 
            className="w-full max-w-xs bg-[#128c7e] text-white py-5 rounded-3xl font-bold text-xl devanagari shadow-2xl active:scale-95 transition-transform"
          >
            नमस्ते, शुरू करें
          </button>
          <p className="mt-4 text-[10px] text-slate-400 font-bold tracking-widest uppercase">Rural Entrepreneur Advisor</p>
        </div>
      ) : view === 'ONBOARDING' ? (
        renderOnboarding()
      ) : view === 'FEEDBACK' ? (
        renderFeedback()
      ) : view === 'DASHBOARD' ? (
        <>
          <header className="bg-[#128c7e] text-white px-4 py-5 flex flex-col shadow-lg z-20">
            <div className="flex justify-between items-center">
              <div className="flex items-center space-x-3">
                <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20 shadow-sm" alt="Avatar" />
                <h1 className="text-lg font-bold devanagari">नमस्ते, {userProfile.name || 'दीदी'}</h1>
              </div>
              <div className="flex space-x-2">
                <button onClick={() => setView('FEEDBACK')} className="bg-white/10 p-2 rounded-xl text-[10px] font-bold devanagari border border-white/10 uppercase">फीडबैक</button>
                <button onClick={handleLogout} className="bg-red-500/20 p-2 rounded-xl text-[10px] font-bold devanagari border border-red-500/10 uppercase text-red-100">लॉगआउट</button>
              </div>
            </div>
            <div className="flex justify-around mt-6 text-[11px] font-bold uppercase tracking-widest border-b border-white/20 pb-2">
              <span className="opacity-60">चैट</span>
              <span className="border-b-2 border-white pb-2 px-6">बिज़नेस विषय</span>
              <span className="opacity-60">मदद</span>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto bg-gray-50/30">
            <div className="p-4 bg-green-50/50 flex items-center space-x-4 border-b border-gray-100 mb-2">
              <div className="w-10 h-10 bg-green-600 rounded-full flex items-center justify-center text-white text-xl shadow-md border border-white"> स </div>
              <div>
                 <h3 className="font-bold devanagari text-green-900">आपकी सहेली सलाहकार</h3>
                 <p className="text-[10px] text-green-700 font-bold uppercase tracking-tighter">हमेशा आपके साथ</p>
              </div>
            </div>
            <div className="divide-y divide-gray-100 bg-white">
              {TOPICS.map((topic) => (
                <button key={topic.id} onClick={() => { setSelectedTopic(topic); setView('CHAT'); }} className="w-full flex items-center p-5 hover:bg-gray-50 active:bg-gray-100 text-left transition-colors">
                  <div className="w-14 h-14 rounded-2xl bg-gray-50 border border-gray-100 flex items-center justify-center text-3xl shadow-sm">{topic.icon}</div>
                  <div className="ml-5 flex-1">
                    <h4 className="font-bold text-[17px] devanagari text-slate-800">{topic.name}</h4>
                    <p className="text-[13px] text-gray-500 devanagari mt-0.5">{topic.desc}</p>
                  </div>
                  <svg className="w-5 h-5 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" /></svg>
                </button>
              ))}
            </div>
          </main>
        </>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white px-4 py-3 flex items-center justify-between shadow-lg z-20">
            <div className="flex items-center">
              <button onClick={() => { closeSession(); setView('DASHBOARD'); setMessages([]); }} className="p-2 mr-1">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
              </button>
              <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20 shadow-md" alt="Saheli" />
              <div className="ml-3">
                <h1 className="text-lg font-bold devanagari leading-none">{selectedTopic?.name}</h1>
                <p className="text-[10px] opacity-90 mt-1 uppercase font-medium tracking-tight">
                  {status === AppStatus.SPEAKING ? 'सहेली बोल रही है...' : status === AppStatus.LISTENING ? 'सुन रही हूँ...' : 'ऑनलाइन'}
                </p>
              </div>
            </div>
            <button onClick={() => { closeSession(); setView('DASHBOARD'); setMessages([]); }} className="p-2 opacity-80">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
            </button>
          </header>

          <main className="flex-1 overflow-y-auto p-3 space-y-4 pb-28 scroll-smooth">
            <div className="flex justify-center my-4"><span className="bg-[#d1e4f2] text-[#4a5e6a] text-[10px] px-3 py-1 rounded-md font-bold uppercase shadow-sm">आज</span></div>
            {messages.length === 0 && (
              <div className="flex justify-center items-center py-10 px-6 text-center">
                <div className="devanagari text-slate-500 text-sm bg-white/90 p-6 rounded-3xl shadow-sm border border-white/50">
                  <p className="font-bold text-lg text-[#128c7e] mb-2">नमस्ते {userProfile.name || 'दीदी'}! 👋</p>
                  <p className="leading-relaxed">नीचे माइक बटन दबाकर बात करना शुरू करें। मैं आपकी मदद के लिए तैयार हूँ।</p>
                </div>
              </div>
            )}
            {messages.map((m, i) => (
              <div key={i} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm ${m.role === 'user' ? 'bubble-user rounded-tr-none' : 'bubble-saheli rounded-tl-none'}`}>
                  <p className="devanagari text-[17px] leading-[1.65] text-slate-800 whitespace-pre-wrap">{m.text}</p>
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>

          <footer className="bg-[#f0f0f0] p-4 flex items-center space-x-4 z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.03)]">
            <div className="flex-1 bg-white rounded-3xl px-6 py-4 shadow-sm flex items-center border border-gray-200">
              <span className="devanagari text-[16px] text-gray-400 font-medium">
                {isRecording ? <span className="text-red-600 animate-pulse font-bold">मैं सुन रही हूँ, बोलिए...</span> : 'पूछने के लिए माइक दबाएं'}
              </span>
            </div>
            <button 
              onMouseDown={() => {
                setMessages(prev => [...prev, { text: "...", role: 'user', timestamp: Date.now() }]);
                toggleRecording(`मुख्य विषय: ${selectedTopic?.name}`);
              }} 
              onMouseUp={() => stopRecordingInternal()} 
              className={`w-16 h-16 rounded-full flex items-center justify-center text-white shadow-xl transition-all active:scale-90 ${isRecording ? 'mic-active bg-red-600' : 'bg-[#128c7e]'}`}
            >
               <svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
            </button>
          </footer>
        </div>
      )}

      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 backdrop-blur-md z-50 flex flex-col items-center justify-center">
          <div className="w-16 h-16 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <h2 className="devanagari text-[#128c7e] text-xl font-bold mt-6">सहेली आ रही है...</h2>
        </div>
      )}

      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.35s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-12px); } }
        .animate-float { animation: float 5s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

export enum AppStatus {
  IDLE = 'IDLE',
  CONNECTING = 'CONNECTING',
  LISTENING = 'LISTENING',
  SPEAKING = 'SPEAKING',
  ERROR = 'ERROR'
}

export interface GroundingLink {
  uri: string;
  title: string;
}

export interface VisualContent {
  type: 'image' | 'map' | 'search' | 'info';
  title?: string;
  url?: string;
  content?: string;
  items?: { title: string; subtitle?: string; url?: string }[];
  groundingLinks?: GroundingLink[];
  isGenerating?: boolean;
}

export interface TranscriptionItem {
  text: string;
  role: 'user' | 'model';
  timestamp: number;
  visual?: VisualContent;
}

export interface UserProfile {
  name: string;
  mobile: string;
  village: string;
  state: string;
  location?: string; // Legacy field
  onboarded: boolean;
}

export interface FeedbackEntry {
  text?: string;
  audioBlob?: Blob;
  timestamp: number;
  userId: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage, Type, FunctionDeclaration } from '@google/genai';
import { AppStatus, TranscriptionItem, VisualContent, UserProfile } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';

const BASE_SYSTEM_INSTRUCTION = `
आपका नाम "उद्योग सहेली" है। आप ग्रामीण महिला उद्यमियों की सच्ची सलाहकार और डिजिटल सहेली हैं।

अनिवार्य नियम (Strict Rules):
1. **सिर्फ देवनागरी लिपि (Strict Devanagari)**: आपका हर शब्द केवल हिंदी देवनागरी लिपि में होना चाहिए। किसी भी परिस्थिति में उर्दू, अरबी या अन्य विदेशी लिपियों का उपयोग न करें।
2. **नाम और नंबर**: यदि यूज़र अपना नाम या नंबर बताता है, तो उसे केवल देवनागरी लिपि में ही लिखें (जैसे: "अमित", "98765...")।
3. **व्यवहार**: यूज़र को "दीदी" या "बहन" कहें। सरल और आत्मीय भाषा का प्रयोग करें।
4. **लक्ष्य**: ग्रामीण महिलाओं को उनके छोटे व्यवसाय में मदद करना।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";
const CDF_LOGO = "https://image2url.com/r2/default/images/1769073801640-26f71cc6-deb8-4340-afee-ef36d5b8f9c9.png";

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0);
  const [userProfile, setUserProfile] = useState<UserProfile>({ 
    name: '', 
    mobile: '', 
    village: '', 
    state: '', 
    onboarded: false 
  });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedbackText, setFeedbackText] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentOutputTranscription = useRef<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('udyog_saheli_profile_v2');
    if (saved) {
      setUserProfile(JSON.parse(saved));
    }
  }, []);

  const saveProfile = (data: UserProfile) => {
    localStorage.setItem('udyog_saheli_profile_v2', JSON.stringify(data));
    setUserProfile(data);
  };

  const handleLogout = () => {
    if (window.confirm("क्या आप वाकई लॉगआउट करना चाहती हैं?")) {
      localStorage.removeItem('udyog_saheli_profile_v2');
      setUserProfile({ name: '', mobile: '', village: '', state: '', onboarded: false });
      setView('WELCOME');
      setOnboardingStep(0);
    }
  };

  const submitFeedback = () => {
    if (!feedbackText.trim()) return alert("कृपया सुझाव लिखें।");
    console.log("Feedback:", feedbackText);
    alert("धन्यवाद दीदी! हमें आपका सुझाव मिल गया है।");
    setFeedbackText('');
    setView('DASHBOARD');
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + (customInstruction ? `\nकार्य: ${customInstruction}` : ""),
        outputAudioTranscription: {},
        inputAudioTranscription: {},
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.inputTranscription) {
            const text = message.serverContent.inputTranscription.text;
            if (view === 'ONBOARDING') {
              if (onboardingStep === 1) setUserProfile(p => ({ ...p, name: text }));
              else if (onboardingStep === 2) setUserProfile(p => ({ ...p, mobile: text }));
              else if (onboardingStep === 3) setUserProfile(p => ({ ...p, village: text }));
              else if (onboardingStep === 4) setUserProfile(p => ({ ...p, state: text }));
            } else if (view === 'FEEDBACK') {
              setFeedbackText(prev => prev + " " + text);
            }
          }
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText && view === 'CHAT') {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now() }]);
            }
            currentOutputTranscription.current = '';
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setError("नेटवर्क की समस्या।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async (instr?: string) => {
    if (!isRecording) {
      stopAudio();
      const session = await initSession(instr);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
    } else {
      stopRecordingInternal();
    }
  };

  const closeSession = () => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    stopAudio();
    setStatus(AppStatus.IDLE);
  };

  const renderOnboarding = () => {
    const steps = [
      { id: 'disclaimer', label: "महत्वपूर्ण सूचना", icon: '⚠️' },
      { id: 'name', label: "आपका नाम क्या है?", key: 'name', type: 'text', icon: '👤' },
      { id: 'mobile', label: "आपका मोबाइल नंबर?", key: 'mobile', type: 'tel', icon: '📱' },
      { id: 'village', label: "आपके गाँव का नाम?", key: 'village', type: 'text', icon: '🏡' },
      { id: 'state', label: "आपका राज्य?", key: 'state', type: 'text', icon: '🇮🇳' }
    ];
    const current = steps[onboardingStep];

    if (current.id === 'disclaimer') {
      return (
        <div className="flex flex-col h-full bg-white p-6 animate-fade-in text-center">
          <div className="flex-1 flex flex-col justify-center space-y-6">
            <div className="text-6xl mb-4">⚠️</div>
            <h2 className="text-2xl font-black text-red-600 devanagari">डिस्क्लेमर (Disclaimer)</h2>
            <div className="bg-red-50 p-6 rounded-3xl border border-red-100 text-left space-y-4">
              <p className="text-[17px] devanagari text-red-900 leading-relaxed font-bold">
                यह ऐप वर्तमान में पायलट फेज (Pilot Phase) में है और केवल शैक्षिक उद्देश्यों के लिए है। 
              </p>
              <p className="text-[15px] devanagari text-red-800 leading-relaxed">
                यह आर्टिफिशियल इंटेलिजेंस (AI) का उपयोग करता है, इसलिए कभी-कभी जानकारी गलत हो सकती है। 
                कृपया महत्वपूर्ण बिज़नेस निर्णय लेने से पहले विशेषज्ञों की सलाह लें।
              </p>
            </div>
          </div>
          <button onClick={() => setOnboardingStep(1)} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl active:scale-95">
            मैं सहमत हूँ
          </button>
        </div>
      );
    }

