const BASE_SYSTEM_INSTRUCTION = `
आपका नाम "उद्योग सहेली" है। आप ग्रामीण महिला उद्यमियों की सच्ची सलाहकार और डिजिटल सहेली हैं।

अनिवार्य नियम (Strict Rules):
1. **सिर्फ देवनागरी लिपि (Strict Devanagari)**: आपका हर शब्द केवल हिंदी देवनागरी लिपि में होना चाहिए। किसी भी परिस्थिति में उर्दू, अरबी या अन्य विदेशी लिपियों का उपयोग न करें।
2. **नाम और नंबर**: यदि यूज़र अपना नाम या नंबर बताता है, तो उसे केवल देवनागरी लिपि में ही लिखें (जैसे: "अमित", "98765...")।
3. **व्यवहार**: यूज़र को "दीदी" या "बहन" कहें। सरल और आत्मीय भाषा का प्रयोग करें।
4. **लक्ष्य**: ग्रामीण महिलाओं को उनके छोटे व्यवसाय में मदद करना।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";
const CDF_LOGO = "https://image2url.com/r2/default/images/1769073801640-26f71cc6-deb8-4340-afee-ef36d5b8f9c9.png";
const HELPLINE_NUMBER = "+91-9911988233";

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0); 
  const [userProfile, setUserProfile] = useState<UserProfile>({ 
    name: '', 
    mobile: '', 
    village: '', 
    state: '', 
    onboarded: false 
  });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [feedbackText, setFeedbackText] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);

  const currentOutputTranscription = useRef<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('udyog_saheli_profile_v4');
    if (saved) {
      setUserProfile(JSON.parse(saved));
    }
  }, []);

  const saveProfile = (data: UserProfile) => {
    localStorage.setItem('udyog_saheli_profile_v4', JSON.stringify(data));
    setUserProfile(data);
  };

  const handleLogout = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (window.confirm("क्या आप वाकई लॉगआउट करना चाहती हैं?")) {
      closeSession();
      localStorage.removeItem('udyog_saheli_profile_v4');
      setUserProfile({ name: '', mobile: '', village: '', state: '', onboarded: false });
      setMessages([]);
      setOnboardingStep(0);
      setView('WELCOME');
    }
  };

  const submitFeedback = () => {
    if (!feedbackText.trim()) return alert("कृपया सुझाव लिखें।");
    alert("धन्यवाद दीदी! हमें आपका सुझाव मिल गया है।");
    setFeedbackText('');
    setView('DASHBOARD');
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: BASE_SYSTEM_INSTRUCTION + `\nयूज़र जानकारी: ${JSON.stringify(userProfile)}` + (customInstruction ? `\nकार्य: ${customInstruction}` : ""),
        outputAudioTranscription: {},
        inputAudioTranscription: {},
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.inputTranscription && view === 'FEEDBACK') {
            setFeedbackText(prev => prev + " " + message.serverContent!.inputTranscription!.text);
          }
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText && view === 'CHAT') {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now() }]);
            }
            currentOutputTranscription.current = '';
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { sourcesRef.current.delete(source); if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); });
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setError("नेटवर्क की समस्या।"),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async (instr?: string) => {
    if (!isRecording) {
      stopAudio();
      const session = await initSession(instr);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const source = audioContextRef.current!.input.createMediaStreamSource(stream);
      const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(4096, 1, 1);
      scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
      source.connect(scriptProcessor);
      scriptProcessor.connect(audioContextRef.current!.input.destination);
      micProcessorRef.current = scriptProcessor;
      setIsRecording(true);
    } else {
      stopRecordingInternal();
    }
  };

  const closeSession = () => {
    if (sessionRef.current) { 
      try { sessionRef.current.close(); } catch(e) {}
      sessionRef.current = null; 
    }
    stopAudio();
    setStatus(AppStatus.IDLE);
  };

  const renderOnboarding = () => {
    if (onboardingStep === 0) {
      return (
        <div className="flex flex-col h-full bg-white p-6 animate-fade-in text-center">
          <div className="flex-1 flex flex-col justify-center space-y-6">
            <div className="text-6xl mb-4">⚠️</div>
            <h2 className="text-2xl font-black text-red-600 devanagari">डिस्क्लेमर (Disclaimer)</h2>
            <div className="bg-red-50 p-6 rounded-3xl border border-red-100 text-left space-y-4 shadow-inner">
              <p className="text-[17px] devanagari text-red-900 leading-relaxed font-bold">
                यह ऐप वर्तमान में पायलट फेज (Pilot Phase) में है और केवल शैक्षिक उद्देश्यों के लिए है। 
              </p>
              <p className="text-[15px] devanagari text-red-800 leading-relaxed">
                यह आर्टिफिशियल इंटेलिजेंस (AI) का उपयोग करता है, इसलिए कभी-कभी जानकारी गलत हो सकती है। 
                कृपया महत्वपूर्ण बिज़नेस निर्णय लेने से पहले विशेषज्ञों की सलाह लें।
              </p>
            </div>
          </div>
          <button onClick={() => setOnboardingStep(1)} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl active:scale-95 transition-transform">
            मैं सहमत हूँ
          </button>
        </div>
      );
    }

    const isFormValid = userProfile.name.trim() && userProfile.mobile.trim() && userProfile.village.trim() && userProfile.state.trim();

    return (
      <div className="flex flex-col h-full bg-white p-6 animate-fade-in overflow-y-auto">
        <header className="flex items-center mb-6">
          <button onClick={() => setOnboardingStep(0)} className="text-gray-400 p-2 -ml-2">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h2 className="flex-1 text-center font-bold devanagari text-slate-800 text-lg">आपकी जानकारी</h2>
          <div className="w-8" />
        </header>

        <div className="space-y-6 pb-6">
          <div className="text-center mb-4">
             <div className="w-16 h-16 bg-green-50 rounded-full mx-auto flex items-center justify-center text-3xl mb-2 border border-green-100">📋</div>
             <p className="devanagari text-gray-500 font-bold text-sm px-4">बेहतर सलाह के लिए अपनी जानकारी भरें</p>
          </div>

          <div className="space-y-4">
            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2 uppercase tracking-wider">शुभ नाम</label>
              <input
                type="text"
                value={userProfile.name}
                onChange={(e) => setUserProfile({ ...userProfile, name: e.target.value })}
                className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all"
                placeholder="अपना नाम लिखें"
              />
            </div>

            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2 uppercase tracking-wider">मोबाइल नंबर</label>
              <input
                type="tel"
                value={userProfile.mobile}
                onChange={(e) => setUserProfile({ ...userProfile, mobile: e.target.value })}
                className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all"
                placeholder="98XXXXXXXX"
              />
            </div>

            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2 uppercase tracking-wider">गाँव का नाम</label>
              <input
                type="text"
                value={userProfile.village}
                onChange={(e) => setUserProfile({ ...userProfile, village: e.target.value })}
                className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all"
                placeholder="गाँव का नाम यहाँ लिखें"
              />
            </div>

            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2 uppercase tracking-wider">राज्य</label>
              <input
                type="text"
                value={userProfile.state}
                onChange={(e) => setUserProfile({ ...userProfile, state: e.target.value })}
                className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all"
                placeholder="उदा. उत्तर प्रदेश"
              />
            </div>
          </div>
        </div>

        <button 
          onClick={() => {
            saveProfile({ ...userProfile, onboarded: true }); 
            setView('DASHBOARD');
          }}
          disabled={!isFormValid}
          className={`w-full py-5 mt-4 rounded-3xl font-bold text-xl devanagari shadow-xl transition-all ${isFormValid ? 'bg-[#128c7e] text-white active:scale-95' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}
        >
          शुरू करें
        </button>
      </div>
    );
  };

  const renderFeedback = () => (
    <div className="flex flex-col h-full bg-white animate-fade-in">
      <header className="bg-[#128c7e] text-white p-4 flex items-center justify-between shadow-md">
        <button onClick={() => setView('DASHBOARD')} className="p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" /></svg></button>
        <h2 className="text-xl font-bold devanagari">सुझाव दें</h2>
        <button onClick={() => setView('DASHBOARD')} className="p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg></button>
      </header>

      <div className="flex-1 p-6 space-y-6 overflow-y-auto">
        <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100">
          <p className="text-[15px] text-blue-900 devanagari font-bold">दीदी, हम इस ऐप को और बेहतर बनाना चाहते हैं। कृपया अपना सुझाव लिखें या बोलकर दें।</p>
        </div>

        <textarea
          value={feedbackText}
          onChange={(e) => setFeedbackText(e.target.value)}
          className="w-full h-40 p-4 rounded-2xl border-2 border-gray-100 focus:border-[#128c7e] focus:outline-none devanagari text-lg shadow-sm"
          placeholder="यहाँ सुझाव लिखें..."
        />

        <button
          onMouseDown={() => toggleRecording("यूज़र से फीडबैक देवनागरी में लें।")}
          onMouseUp={() => stopRecordingInternal()}
          className={`w-full py-6 rounded-3xl flex flex-col items-center justify-center space-y-2 transition-all ${isRecording ? 'bg-red-500 text-white shadow-2xl scale-105' : 'bg-gray-50 text-gray-600 border border-gray-100'}`}
        >
          <svg className={`w-8 h-8 ${isRecording ? 'text-white' : 'text-[#128c7e]'}`} fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/></svg>
          <span className="font-bold devanagari text-lg">{isRecording ? "सुन रही हूँ, बोलिये..." : "बोलकर सुझाव दें"}</span>
        </button>
      </div>

      <div className="p-6">
        <button onClick={submitFeedback} className="w-full py-5 rounded-3xl font-bold text-xl devanagari bg-[#128c7e] text-white shadow-xl active:scale-95 transition-transform">सुझाव भेजें</button>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-6 w-full max-w-xs">
            <div className="relative w-full h-72 animate-float flex items-center justify-center">
                <div className="absolute inset-0 bg-green-100/40 rounded-[60px] blur-3xl scale-90"></div>
                <img src={SAHELI_IMAGE} alt="Saheli Logo" className="relative z-10 w-full h-full object-contain rounded-3xl shadow-2xl" />
            </div>
            <div className="space-y-2">
              <h1 className="text-4xl font-black text-green-900 devanagari">उद्योग सहेली</h1>
              <p className="text-lg text-green-700 font-bold devanagari italic leading-tight">ग्रामीण उद्यमियों के सपनों को पंख देने वाली आपकी बिज़नेस पार्टनर</p>
            </div>
          </div>

          <div className="w-full flex flex-col items-center space-y-6">
            <div className="space-y-4 w-full flex flex-col items-center">
              <button onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} className="w-full max-w-xs bg-[#128c7e] text-white py-5 rounded-3xl font-bold text-xl devanagari shadow-2xl active:scale-95 transition-transform">
                नमस्ते, शुरू करें
              </button>

              <a href={`tel:${HELPLINE_NUMBER}`} className="flex items-center space-x-2 bg-white px-4 py-2 rounded-full border border-green-100 shadow-sm text-green-800 font-bold">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M6.62 10.79c1.44 2.82 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z"/></svg>
                <span className="text-xs devanagari">हेल्पलाइन: {HELPLINE_NUMBER}</span>
              </a>
            </div>

            <div className="flex flex-col items-center space-y-2 pb-2">
              <p className="text-[9px] text-gray-400 font-black uppercase tracking-widest">Powered By</p>
              <img src={CDF_LOGO} alt="CDF Logo" className="h-10 object-contain grayscale opacity-60" />
              <p className="text-[9px] text-gray-400 devanagari font-bold uppercase">Connecting Dreams Foundation</p>
            </div>
          </div>
        </div>
      ) : view === 'ONBOARDING' ? (
        renderOnboarding()
      ) : view === 'FEEDBACK' ? (
        renderFeedback()
      ) : view === 'DASHBOARD' ? (
        <>
          <header className="bg-[#128c7e] text-white px-4 py-5 flex flex-col shadow-lg z-20">
            <div className="flex justify-between items-center">
              <div className="flex items-center space-x-3">
                <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20 shadow-sm" alt="Saheli" />
                <h1 className="text-lg font-bold devanagari truncate max-w-[120px]">नमस्ते, {userProfile.name || 'दीदी'}</h1>
              </div>
              <div className="flex space-x-1.5">
                <button onClick={() => setView('FEEDBACK')} className="bg-white/10 p-2 rounded-xl text-[10px] font-bold devanagari border border-white/10">फीडबैक</button>
                <button 
                  onClick={(e) => handleLogout(e)} 
                  className="bg-red-500/20 p-2 rounded-xl text-[10px] font-bold devanagari border border-red-500/10 text-red-100"
                >
                  लॉगआउट
                </button>
              </div>
            </div>
            <div className="flex justify-around mt-6 text-[10px] font-black uppercase tracking-widest border-b border-white/20 pb-2">
              <span className="opacity-40">मदद</span>
              <span className="border-b-2 border-white pb-2 px-6">बिज़नेस सलाह</span>
              <span className="opacity-40">प्रोफ़ाइल</span>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto bg-gray-50/20 pb-6">
            <div className="p-5 bg-green-50/40 border-b border-gray-100 flex items-center justify-between mb-2">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-[#128c7e] rounded-xl flex items-center justify-center text-white text-xl font-black shadow-md">स</div>
                <div>
                  <h3 className="font-bold devanagari text-green-900 leading-none mb-1">सहेली सलाहकार</h3>
                  <p className="text-[9px] text-green-700 font-bold uppercase tracking-widest">Digital Assistant</p>
                </div>
              </div>
              <div className="text-[10px] bg-green-100 text-green-800 px-2 py-1 rounded-md font-bold uppercase">Live AI</div>
            </div>

            <div className="divide-y divide-gray-100 bg-white shadow-sm mb-6">
              {TOPICS.map((topic) => (
