          0% { transform: scale(1); opacity: 0.6; }
          100% { transform: scale(1.6); opacity: 0; }
        }
        .pulse-animation {
          animation: pulse-custom 2s infinite ease-out;
        }
      `}</style>
    </div>
  );
};

