              onMouseUp={() => stopRecordingInternal()} 
              onTouchStart={() => { if(messages.length === 0 || messages[messages.length-1].text !== '...') setMessages(prev => [...prev, { text: "...", role: 'user', timestamp: Date.now() }]); toggleRecording(); }} 
              onTouchEnd={() => stopRecordingInternal()}
            >
              <div className="relative w-12 h-12 flex items-center justify-center">
                {isRecording && <div className="absolute w-full h-full rounded-full bg-[#128c7e]/20 animate-ping" />}
