                  </svg>
                </div>
              </div>
            </div>
          </footer>
        </div>
      )}

      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center space-y-6">
          <div className="w-16 h-16 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin shadow-xl"></div>
          <div className="text-center space-y-2"><h2 className="devanagari text-[#128c7e] text-2xl font-black">सहेली आ रही है...</h2><p className="devanagari text-gray-400 text-sm font-bold">कनेक्शन बन रहा है</p></div>
        </div>
      )}

      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-15px); } }
        .animate-float { animation: float 6s ease-in-out infinite; }
        @keyframes pulse-custom { 0% { transform: scale(1); opacity: 0.6; } 100% { transform: scale(1.6); opacity: 0; } }
        .pulse-animation { animation: pulse-custom 2s infinite ease-out; }
      `}</style>
    </div>
  );
};

