अनिवार्य नियम (Strict Rules):
1. **सिर्फ देवनागरी लिपि (Strict Devanagari)**: आपका हर शब्द केवल हिंदी देवनागरी लिपि में होना चाहिए।
2. **व्यवहार**: यूज़र को "दीदी" या "बहन" कहें। सरल और आत्मीय भाषा का प्रयोग करें।
3. **ग्रामीण बोली की समझ (Dialect Sensitivity)**: 
   - यूज़र ग्रामीण इलाकों से हैं और उनकी हिंदी में क्षेत्रीय बोलियों (जैसे भोजपुरी, बघेली, बुंदेली, मारवाड़ी, हरियाणवी आदि) का पुट हो सकता है।
   - यदि यूज़र कुछ शब्दों का उच्चारण अलग तरह से करें (जैसे 'पैसा' को 'पईसा', 'कहाँ' को 'कइसा' या 'काहें'), तो आप उनके भाव और संदर्भ को समझें।
   - व्याकरण की शुद्धता से अधिक उनके व्यवसाय की समस्या को हल करने पर ध्यान दें।
   - यदि कोई शब्द समझ न आए, तो विनम्रता से पूछें: "दीदी, क्या आप इस बात को फिर से सरल शब्दों में बता सकती हैं?"
4. **लक्ष्य**: ग्रामीण महिलाओं को उनके छोटे व्यवसाय (जैसे सिलाई, अचार-पापड़, ब्यूटी पार्लर, किराना दुकान, खेती-बाड़ी) में व्यावहारिक मदद करना।
`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";
const CDF_LOGO = "https://image2url.com/r2/default/images/1769073801640-26f71cc6-deb8-4340-afee-ef36d5b8f9c9.png";
const HELPLINE_NUMBER = "+91-9911988233";
const PROFILE_KEY = 'udyog_saheli_v7_profile';

const INDIAN_STATES = [
  "आंध्र प्रदेश", "अरुणाचल प्रदेश", "असम", "बिहार", "छत्तीसगढ़", "गोवा", "गुजरात", "Haryana", 
  "हिमाचल प्रदेश", "झारखंड", "कर्नाटक", "केरल", "मध्य प्रदेश", "महाराष्ट्र", "मणिपुर", 
  "मेघालय", "मिजोरम", "नागालैंड", "ओडिशा", "पंजाब", "राजस्थान", "सिक्किम", "तमिलनाडु", 
  "तेलंगाना", "त्रिपुरा", "उत्तर प्रदेश", "उत्तराखंड", "पश्चिम बंगाल", "दिल्ली", "जम्मू और कश्मीर"
];

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0); 
  const [userProfile, setUserProfile] = useState<UserProfile>({ 
    name: '', mobile: '', village: '', state: '', onboarded: false 
  });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');
  const [chatInput, setChatInput] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const currentOutputTranscription = useRef<string>('');

  useEffect(() => {
    const saved = localStorage.getItem(PROFILE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setUserProfile(parsed);
      if (parsed.onboarded) setView('DASHBOARD');
    }
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  const saveProfile = (data: UserProfile) => {
    localStorage.setItem(PROFILE_KEY, JSON.stringify(data));
    setUserProfile(data);
  };

  const handleLogout = (e: React.MouseEvent) => {
    e.preventDefault();
    if (window.confirm("क्या आप वाकई लॉगआउट करना चाहती हैं?")) {
      closeSession();
      localStorage.removeItem(PROFILE_KEY);
      setUserProfile({ name: '', mobile: '', village: '', state: '', onboarded: false });
      setMessages([]);
      setOnboardingStep(0);
      setView('WELCOME');
    }
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const dynamicInstruction = `
${BASE_SYSTEM_INSTRUCTION}
यूज़र की जानकारी:
- नाम: ${userProfile.name}
- राज्य: ${userProfile.state}
- गाँव: ${userProfile.village}

निर्देश: यूज़र ${userProfile.state} के ${userProfile.village} गाँव से हैं। कृपया उनके क्षेत्रीय संदर्भ के प्रति संवेदनशील रहें।
${customInstruction ? `\nवर्तमान कार्य: ${customInstruction}` : ""}
`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: dynamicInstruction,
        outputAudioTranscription: {},
        inputAudioTranscription: {},
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.outputTranscription) currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText && view === 'CHAT') {
              setMessages(prev => [...prev, { text: modelText, role: 'model', timestamp: Date.now() }]);
            }
            currentOutputTranscription.current = '';
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { 
              sourcesRef.current.delete(source); 
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); 
            });
            const startTime = Math.max(nextStartTimeRef.current, ctx.currentTime + 0.05); 
            source.start(startTime);
            nextStartTimeRef.current = startTime + audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setStatus(AppStatus.ERROR),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      stopAudio();
      try {
        const session = await initSession(`मुख्य विषय: ${selectedTopic?.name}`);
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        streamRef.current = stream;
        const source = audioContextRef.current!.input.createMediaStreamSource(stream);
        const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(2048, 1, 1); 
        scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
        source.connect(scriptProcessor);
        scriptProcessor.connect(audioContextRef.current!.input.destination);
        micProcessorRef.current = scriptProcessor;
        setIsRecording(true);
      } catch (err) {
        console.error(err);
        setStatus(AppStatus.ERROR);
      }
    } else {
      stopRecordingInternal();
    }
  };

  const handleSendText = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!chatInput.trim()) return;

    stopAudio();
    const textToSend = chatInput;
    setChatInput('');
    setMessages(prev => [...prev, { text: textToSend, role: 'user', timestamp: Date.now() }]);

    try {
      const session = await initSession(`यूज़र ने संदेश टाइप किया है। विषय: ${selectedTopic?.name}`);
      session.sendRealtimeInput({ parts: [{ text: textToSend }] });
    } catch (err) {
      console.error(err);
    }
  };

  const closeSession = () => {
    if (sessionRef.current) { try { sessionRef.current.close(); } catch(e) {} sessionRef.current = null; }
    stopAudio();
    setStatus(AppStatus.IDLE);
  };

  const renderOnboarding = () => {
    if (onboardingStep === 0) {
      return (
        <div className="flex flex-col h-full bg-white p-6 animate-fade-in text-center">
          <div className="flex-1 flex flex-col justify-center space-y-6">
            <div className="text-6xl mb-4">⚠️</div>
            <div className="flex items-center justify-center space-x-2 text-red-600">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
               </svg>
               <h2 className="text-2xl font-black devanagari">महत्वपूर्ण सूचना (Disclaimer)</h2>
            </div>

            <div className="space-y-4">
              <div className="bg-red-50 p-5 rounded-3xl border border-red-100 text-left shadow-inner">
                <p className="text-[17px] devanagari text-red-900 leading-relaxed font-bold">
                  दीदी, यह ऐप अभी सीखने के दौर (Pilot Phase) में है और केवल आपको जानकारी देने के लिए बनाया गया है।
                </p>
              </div>

              <div className="bg-orange-50 p-5 rounded-3xl border border-orange-100 text-left shadow-inner">
                <p className="text-[15px] devanagari text-orange-900 leading-relaxed">
                  यह तकनीक (AI) पर आधारित है, इसलिए कभी-कभी जानकारी पूरी तरह सही नहीं हो सकती। कृपया कोई भी बड़ा बिज़नेस फैसला लेने से पहले विशेषज्ञों की सलाह ज़रूर लें।
                </p>
              </div>

              <div className="bg-blue-50 p-5 rounded-3xl border border-blue-100 text-left shadow-inner">
                <p className="text-[14px] devanagari text-blue-900 leading-relaxed font-semibold">
                  आपकी जानकारी का उपयोग केवल आपको बेहतर और व्यक्तिगत सलाह देने के लिए किया जाता है।
                </p>
              </div>
            </div>
          </div>

          <button onClick={() => setOnboardingStep(1)} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl active:scale-95 transition-transform">
            मैं सहमत हूँ और शुरू करना चाहती हूँ
          </button>
        </div>
      );
    }

    const isFormValid = userProfile.name.trim() && userProfile.mobile.trim() && userProfile.village.trim() && userProfile.state.trim();

    return (
      <div className="flex flex-col h-full bg-white p-6 animate-fade-in overflow-y-auto">
        <header className="flex items-center mb-6">
          <button onClick={() => setOnboardingStep(0)} className="text-gray-400 p-2 -ml-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
          <h2 className="flex-1 text-center font-bold devanagari text-slate-800 text-lg">आपकी जानकारी</h2>
          <div className="w-8" />
        </header>

        <div className="space-y-6 pb-6 flex-1">
          <div className="text-center mb-4">
             <div className="w-16 h-16 bg-green-50 rounded-full mx-auto flex items-center justify-center text-3xl mb-2 border border-green-100">👤</div>
             <p className="devanagari text-gray-500 font-bold text-sm px-4">कृपया अपनी जानकारी भरें</p>
          </div>

          <div className="space-y-4">
            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2">शुभ नाम</label>
              <input type="text" value={userProfile.name} onChange={(e) => setUserProfile({ ...userProfile, name: e.target.value })} className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all shadow-sm" placeholder="अपना नाम लिखें" />
            </div>
            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2">मोबाइल नंबर</label>
              <input type="tel" value={userProfile.mobile} onChange={(e) => setUserProfile({ ...userProfile, mobile: e.target.value })} className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all shadow-sm" placeholder="98XXXXXXXX" />
            </div>
            <div className="space-y-1">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2">गाँव का नाम</label>
              <input type="text" value={userProfile.village} onChange={(e) => setUserProfile({ ...userProfile, village: e.target.value })} className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all shadow-sm" placeholder="गाँव का नाम लिखें" />
            </div>
            <div className="space-y-1 relative">
              <label className="devanagari text-slate-600 font-bold text-xs ml-2">राज्य चुनें</label>
              <select value={userProfile.state} onChange={(e) => setUserProfile({ ...userProfile, state: e.target.value })} className="w-full text-base font-bold p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] focus:bg-white focus:outline-none devanagari transition-all shadow-sm appearance-none">
                <option value="">अपना राज्य चुनें</option>
                {INDIAN_STATES.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
              <div className="absolute right-4 bottom-5 pointer-events-none text-gray-400"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg></div>
            </div>
          </div>
        </div>

        <button onClick={() => { saveProfile({ ...userProfile, onboarded: true }); setView('DASHBOARD'); }} disabled={!isFormValid} className={`w-full py-5 mt-4 rounded-3xl font-bold text-xl devanagari shadow-xl transition-all ${isFormValid ? 'bg-[#128c7e] text-white active:scale-95' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}>शुरू करें</button>
      </div>
    );
  };

  const renderFeedback = () => (
    <div className="flex flex-col h-full bg-white animate-fade-in">
      <header className="bg-[#128c7e] text-white p-4 flex items-center justify-between shadow-md">
        <button onClick={() => setView('DASHBOARD')} className="p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" /></svg></button>
        <h2 className="text-xl font-bold devanagari">सुझाव दें</h2>
        <div className="w-10" />
      </header>
      <div className="flex-1 p-6 space-y-6 overflow-y-auto">
        <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100"><p className="text-[15px] text-blue-900 devanagari font-bold">दीदी, कृपया अपना सुझाव लिखें। आपके सुझाव हमारे लिए महत्वपूर्ण हैं।</p></div>
        <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} className="w-full h-48 p-4 rounded-2xl border-2 border-gray-100 focus:border-[#128c7e] focus:outline-none devanagari text-lg shadow-sm" placeholder="यहाँ सुझाव लिखें..." />
      </div>
      <div className="p-6">
        <button onClick={() => { if(!feedbackText.trim()) return alert("कृपया सुझाव लिखें।"); alert("धन्यवाद दीदी! हमें आपका सुझाव मिल गया है।"); setFeedbackText(''); setView('DASHBOARD'); }} className="w-full py-5 rounded-3xl font-bold text-xl devanagari bg-[#128c7e] text-white shadow-xl active:scale-95 transition-transform">सुझाव भेजें</button>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-6 w-full max-w-xs">
            <div className="relative w-full h-72 animate-float flex items-center justify-center">
                <div className="absolute inset-0 bg-green-100/40 rounded-[60px] blur-3xl scale-90"></div>
                <img src={SAHELI_IMAGE} alt="Saheli Logo" className="relative z-10 w-full h-full object-contain rounded-3xl shadow-2xl" />
            </div>
            <div className="space-y-2">
              <h1 className="text-4xl font-black text-green-900 devanagari">उद्योग सहेली</h1>
              <p className="text-lg text-green-700 font-bold devanagari italic leading-tight">ग्रामीण उद्यमियों के सपनों की सच्ची साथी</p>
            </div>
          </div>

          <div className="w-full flex flex-col items-center space-y-8">
            <button onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} className="w-full max-w-xs bg-[#128c7e] text-white py-5 rounded-3xl font-bold text-xl devanagari shadow-xl active:scale-95 transition-transform">नमस्ते, शुरू करें</button>
            <div className="flex flex-col items-center space-y-2 pb-2">
              <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest">Powered By</p>
              <img src={CDF_LOGO} alt="Connecting Dreams Foundation Logo" className="h-16 object-contain transition-all filter drop-shadow-lg" />
              <p className="text-[11px] text-green-800 devanagari font-black uppercase tracking-tight">Connecting Dreams Foundation</p>
            </div>
          </div>
        </div>
      ) : view === 'ONBOARDING' ? (
        renderOnboarding()
      ) : view === 'FEEDBACK' ? (
        renderFeedback()
      ) : view === 'DASHBOARD' ? (
        <div className="flex flex-col h-full bg-white">
          <header className="bg-[#128c7e] text-white px-4 py-5 flex flex-col shadow-lg z-20">
            <div className="flex justify-between items-center">
              <div className="flex items-center space-x-3">
                <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20 shadow-sm" alt="Saheli" />
                <h1 className="text-lg font-bold devanagari truncate max-w-[120px]">नमस्ते, {userProfile.name}</h1>
              </div>
              <div className="flex items-center space-x-2">
                <button onClick={() => setView('FEEDBACK')} className="bg-white/10 px-3 py-2 rounded-xl text-[10px] font-bold devanagari border border-white/10 text-white uppercase active:bg-white/20 transition-all">फीडबैक</button>
