import { UserProfile, TranscriptionItem } from '../types';

/**
 * BACKEND CONFIGURATION
 * Replace 'YOUR_BACKEND_URL' with your actual server endpoint (e.g., Supabase, Firebase, or a Custom API).
 */
const BACKEND_URL = 'https://your-api-endpoint.com/api'; 
const API_KEY = 'your-secret-api-key'; // If required by your backend

export const dbService = {
  /**
   * Syncs user profile to the central database.
   * This allows you to track WHO is using the app and WHERE they are from.
   */
  async syncProfile(profile: UserProfile): Promise<boolean> {
    console.log('[DB Sync] Attempting to save profile...', profile);

    try {
      const response = await fetch(`${BACKEND_URL}/profiles`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${API_KEY}`
        },
        body: JSON.stringify({
          ...profile,
          device_info: navigator.userAgent,
          created_at: new Date().toISOString()
        }),
      });

      if (!response.ok) throw new Error('Failed to sync profile');

      console.log('[DB Sync] Profile successfully saved to cloud.');
      return true;
    } catch (error) {
      console.warn('[DB Sync] Server not reached. Data stored locally only.', error);
      // In a real app, you might use IndexedDB to retry this later when online
      return false;
    }
  },

  /**
   * Logs a single chat interaction (User Question or Saheli Answer).
   * This data is the "Gold Mine" for training your AI to understand rural dialects better.
   */
  async logInteraction(userId: string, message: TranscriptionItem): Promise<void> {
    console.log(`[DB Log] Logging turn for ${userId}:`, message.text);

    try {
      // We don't 'await' here to keep the UI snappy
      fetch(`${BACKEND_URL}/logs`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${API_KEY}`
        },
        body: JSON.stringify({
          mobile: userId,
          role: message.role,
          content: message.text,
          timestamp: new Date(message.timestamp).toISOString()
        }),
      }).catch(err => console.error('Silent log failure:', err));
    } catch (error) {
      // Silently fail to not interrupt user experience
    }
  }
};

