/**
 * GOOGLE CLOUD CONFIGURATION
 * 
 * To see your data in the Google Cloud Console:
 * 1. Enable "Firestore" in your GCP Project.
 * 2. Create a "Cloud Function" to act as the bridge.
 * 3. Paste the Trigger URL of that function below.
 */
const GCP_FUNCTION_URL = 'https://YOUR_REGION-YOUR_PROJECT.cloudfunctions.net/logInteraction';

export const dbService = {
  /**
   * Syncs user profile to Google Cloud.
   * View this in: GCP Console -> Firestore -> 'profiles' collection.
   */
  async syncProfile(profile: UserProfile): Promise<boolean> {
    console.log('[GCP Sync] Sending profile to cloud...', profile.name);

    try {
      // If you are using Firebase/Firestore directly, you would use the SDK here.
      // For a standard GCP deployment, we use a fetch to a Cloud Function.
      const response = await fetch(GCP_FUNCTION_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'PROFILE_SYNC',
          payload: {
            ...profile,
            timestamp: new Date().toISOString(),
            platform: 'web-gcp-deploy'
          }
        }),
      });

      if (!response.ok) throw new Error('Cloud sync failed');

      console.log('[GCP Sync] Profile data is now visible in your GCP Dashboard.');
      return true;
    } catch (error) {
      console.warn('[GCP Sync] Note: Backend not yet connected. Using local storage.', error);
      return false;
    }
  },

  /**
   * Logs chat interactions for training.
   * View this in: GCP Console -> Logs Explorer (Search for 'interaction_log') 
   * or Firestore -> 'conversations' collection.
   */
  async logInteraction(userId: string, message: TranscriptionItem): Promise<void> {
    const logEntry = {
      mobile: userId,
      role: message.role,
      text: message.text,
      topic: 'business_consultation',
      timestamp: new Date(message.timestamp).toISOString()
    };

    try {
      // This sends data to your GCP backend
      fetch(GCP_FUNCTION_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'CHAT_LOG',
          payload: logEntry
        }),
      }).catch(() => {}); // Silent catch for background logging

      // Also logging to Browser Console for immediate debugging during deployment
      console.debug('[Interaction Stored]', logEntry);
    } catch (error) {
      // Interaction logging should never block the user UI
    }
  }
};

