/**
 * PRODUCTION GOOGLE CLOUD CONFIGURATION
 * 
 * 1. Go to GCP Console -> Cloud Functions.
 * 2. Create a "HTTP Trigger" function named 'logInteraction'.
 * 3. Use the following Node.js logic in your Cloud Function to save to Firestore:
 * 
 *    exports.logInteraction = async (req, res) => {
 *      const admin = require('firebase-admin');
 *      if (!admin.apps.length) admin.initializeApp();
 *      const db = admin.firestore();
 *      const { type, payload } = req.body;
 *      const collection = type === 'PROFILE_SYNC' ? 'profiles' : 'conversations';
 *      await db.collection(collection).add(payload);
 *      res.status(200).send({ status: 'success' });
 *    };
 */

// Replace this with your actual triggered URL after creating the function in GCP
const GCP_FUNCTION_URL = 'https://YOUR_REGION-YOUR_PROJECT.cloudfunctions.net/logInteraction';

export const dbService = {
  /**
   * Syncs user profile to Google Cloud.
   * This is critical for knowing WHO your entrepreneurs are.
   */
  async syncProfile(profile: UserProfile): Promise<boolean> {
    console.log('[GCP Deployment] Syncing profile for:', profile.name);

    try {
      const response = await fetch(GCP_FUNCTION_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        mode: 'cors',
        body: JSON.stringify({
          type: 'PROFILE_SYNC',
          payload: {
            ...profile,
            deployment_env: 'GCP_PILOT_V1',
            synced_at: new Date().toISOString()
          }
        }),
      });

      if (!response.ok) throw new Error('Sync endpoint unreachable');
      return true;
    } catch (error) {
      // We log locally so the pilot can continue even if the network is spotty
      console.warn('[Offline Mode] Profile saved to device. Cloud sync will retry on next interaction.', error);
      return false;
    }
  },

  /**
   * Logs every question and answer.
   * This is your training dataset.
   */
  async logInteraction(userId: string, message: TranscriptionItem): Promise<void> {
    const logEntry = {
      user_id: userId,
      role: message.role,
      text: message.text,
      timestamp: new Date(message.timestamp).toISOString(),
      session_id: window.crypto.randomUUID ? window.crypto.randomUUID() : 'legacy_session'
    };

    try {
      fetch(GCP_FUNCTION_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        mode: 'cors',
        body: JSON.stringify({
          type: 'CHAT_LOG',
          payload: logEntry
        }),
      }).catch(() => {}); 

      // Verification log for your final test run
      console.debug('[GCP Data Pipe] Interaction logged successfully:', message.role);
    } catch (error) {
      // Non-blocking
    }
  }
};

