  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const dynamicInstruction = `${BASE_SYSTEM_INSTRUCTION}\nयूज़र: ${userProfile.name}, गाँव: ${userProfile.village}, राज्य: ${userProfile.state}\n${customInstruction || ""}`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: dynamicInstruction,
        outputAudioTranscription: {},
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          if (message.serverContent?.outputTranscription) {
            currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          }
          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText) {
              const modelMsg: TranscriptionItem = { text: modelText, role: 'model', timestamp: Date.now() };
              setMessages(prev => [...prev, modelMsg]);
              dbService.logInteraction(userProfile.mobile, modelMsg);
            }
            currentOutputTranscription.current = '';
          }
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { 
              sourcesRef.current.delete(source); 
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); 
            });
            const startTime = Math.max(nextStartTimeRef.current, ctx.currentTime + 0.05); 
            source.start(startTime);
            nextStartTimeRef.current = startTime + audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setStatus(AppStatus.ERROR),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      stopAudio();
      try {
        const session = await initSession(`विषय: ${selectedTopic?.name}`);
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        streamRef.current = stream;
        const source = audioContextRef.current!.input.createMediaStreamSource(stream);
        const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(2048, 1, 1); 
        scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
        source.connect(scriptProcessor);
        scriptProcessor.connect(audioContextRef.current!.input.destination);
        micProcessorRef.current = scriptProcessor;
        setIsRecording(true);
      } catch (err) {
        setStatus(AppStatus.ERROR);
      }
    } else {
      stopRecordingInternal();
    }
  };

  const handleSendText = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!chatInput.trim()) return;
    const textToSend = chatInput;
    setChatInput('');
    const userMsg: TranscriptionItem = { text: textToSend, role: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    dbService.logInteraction(userProfile.mobile, userMsg);

    try {
      const session = await initSession();
      session.sendRealtimeInput({ parts: [{ text: textToSend }] });
    } catch (err) {}
  };

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-6">
            <img src={SAHELI_IMAGE} alt="Saheli" className="w-64 h-64 object-contain rounded-3xl shadow-2xl animate-float" />
            <div className="space-y-2">
              <h1 className="text-4xl font-black text-green-900 devanagari">उद्योग सहेली</h1>
              <p className="text-lg text-green-700 font-bold devanagari">ग्रामीण उद्यमियों की डिजिटल साथी</p>
            </div>
          </div>
          <button onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} className="w-full max-w-xs bg-[#128c7e] text-white py-5 rounded-3xl font-bold text-xl devanagari shadow-xl active:scale-95 transition-transform">नमस्ते, शुरू करें</button>
        </div>
      ) : view === 'ONBOARDING' ? (
        <div className="flex flex-col h-full bg-white p-6 animate-fade-in overflow-y-auto">
          {onboardingStep === 0 ? (
            <div className="flex-1 flex flex-col justify-center space-y-8 text-center">
              <div className="text-6xl">📝</div>
              <h2 className="text-2xl font-black devanagari">ज़रूरी जानकारी</h2>
              <div className="space-y-4">
                <div className="bg-blue-50 p-5 rounded-3xl text-left border border-blue-100">
                  <p className="devanagari text-blue-900 font-bold">दीदी, हम आपकी जानकारी को सुरक्षित रखते हैं। इसका उपयोग केवल आपको बेहतर सलाह देने के लिए किया जाएगा।</p>
                </div>
              </div>
              <button onClick={() => setOnboardingStep(1)} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl">आगे बढ़ें</button>
            </div>
          ) : (
            <div className="space-y-6 pt-4">
              <h2 className="text-xl font-bold devanagari text-center">अपनी जानकारी भरें</h2>
              <input type="text" placeholder="नाम" value={userProfile.name} onChange={e => setUserProfile({...userProfile, name: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
              <input type="tel" placeholder="मोबाइल नंबर" value={userProfile.mobile} onChange={e => setUserProfile({...userProfile, mobile: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
              <input type="text" placeholder="गाँव" value={userProfile.village} onChange={e => setUserProfile({...userProfile, village: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
              <select value={userProfile.state} onChange={e => setUserProfile({...userProfile, state: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold">
                <option value="">राज्य चुनें</option>
                {INDIAN_STATES.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <button onClick={() => { saveProfile({...userProfile, onboarded: true}); setView('DASHBOARD'); }} disabled={!userProfile.name || !userProfile.mobile} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl disabled:bg-gray-300">शुरू करें</button>
            </div>
          )}
        </div>
      ) : view === 'DASHBOARD' ? (
        <div className="flex flex-col h-full bg-gray-50">
          <header className="bg-[#128c7e] text-white p-5 flex justify-between items-center shadow-md">
            <div className="flex items-center space-x-3">
              <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20" alt="Saheli" />
              <h1 className="font-bold devanagari">नमस्ते, {userProfile.name}</h1>
            </div>
            <div className="bg-white/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest">Cloud Synced</div>
          </header>
          <div className="p-4 bg-blue-600 text-white text-xs font-bold text-center devanagari">आपकी बातचीत सुरक्षित रूप से गूगल क्लाउड पर स्टोर की जा रही है।</div>
          <main className="flex-1 overflow-y-auto p-4 space-y-4">
            {TOPICS.map(topic => (
              <button key={topic.id} onClick={() => { setSelectedTopic(topic); setView('CHAT'); }} className="w-full bg-white p-5 rounded-3xl flex items-center shadow-sm active:scale-95 transition-transform text-left border border-gray-100">
                <div className="text-4xl mr-4">{topic.icon}</div>
                <div><h4 className="font-bold text-lg devanagari text-slate-800">{topic.name}</h4><p className="text-xs text-gray-400 devanagari">{topic.desc}</p></div>
              </button>
            ))}
          </main>
          <footer className="p-6 flex flex-col items-center">
            <img src={CDF_LOGO} className="h-10 opacity-60 grayscale mb-2" alt="CDF" />
            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">Connecting Dreams Foundation</p>
          </footer>
        </div>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white p-4 flex items-center shadow-lg z-20">
            <button onClick={() => { stopAudio(); setView('DASHBOARD'); setMessages([]); }} className="mr-3"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg></button>
            <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full mr-3" alt="Saheli" />
            <h1 className="font-bold devanagari flex-1">{selectedTopic?.name}</h1>
            <div className="flex space-x-1"><div className={`w-2 h-2 rounded-full ${status === AppStatus.LISTENING ? 'bg-green-400 animate-pulse' : 'bg-white/30'}`} /></div>
          </header>
          <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm devanagari text-[17px] ${m.role === 'user' ? 'bubble-user' : 'bubble-saheli'}`}>{m.text}</div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>
          <footer className="absolute bottom-0 w-full p-2 flex items-end space-x-2 bg-transparent z-30">
            <form onSubmit={handleSendText} className="flex-1 bg-white rounded-3xl flex items-center px-4 py-1 shadow-md">
              <input type="text" value={chatInput} onChange={e => setChatInput(e.target.value)} placeholder="यहाँ लिखें..." className="flex-1 bg-transparent py-3 focus:outline-none devanagari" />
              {chatInput.trim() && <button type="submit" className="text-[#128c7e] ml-2 font-bold devanagari">भेजें</button>}
            </form>
            <div onMouseDown={() => toggleRecording()} onMouseUp={() => stopRecordingInternal()} onTouchStart={() => toggleRecording()} onTouchEnd={() => stopRecordingInternal()} className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl transition-all ${isRecording ? 'bg-red-500 scale-110' : 'bg-[#128c7e]'}`}>
              <svg className="h-6 w-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" /></svg>
            </div>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && <div className="absolute inset-0 bg-white/90 z-50 flex flex-col items-center justify-center space-y-4"><div className="w-12 h-12 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin" /><p className="devanagari font-bold text-[#128c7e]">सहेली आ रही है...</p></div>}
    </div>
  );
};

