                  {m.text}
                  {m.visual?.groundingLinks && (
                    <div className="mt-4 pt-3 border-t border-gray-100">
                      <p className="text-xs font-bold text-gray-500 mb-2">जानकारी के स्रोत:</p>
                      <div className="space-y-2">
                        {m.visual.groundingLinks.map((link, idx) => (
                          <a key={idx} href={link.uri} target="_blank" rel="noopener noreferrer" className="block text-sm text-[#128c7e] font-bold underline truncate">
                            {link.title}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>
          <footer className="absolute bottom-0 w-full p-2 flex items-end space-x-2 bg-transparent z-30">
            <form onSubmit={handleSendText} className="flex-1 bg-white rounded-3xl flex items-center px-4 py-1 shadow-md">
              <input type="text" value={chatInput} onChange={e => setChatInput(e.target.value)} placeholder="यहाँ लिखें..." className="flex-1 bg-transparent py-3 focus:outline-none devanagari" />
              {chatInput.trim() && <button type="submit" className="text-[#128c7e] ml-2 font-bold devanagari">भेजें</button>}
            </form>
            <button 
              onMouseDown={() => toggleRecording()} 
              onMouseUp={() => stopRecordingInternal()} 
              onTouchStart={() => toggleRecording()} 
              onTouchEnd={() => stopRecordingInternal()} 
              className={`w-14 h-14 rounded-full flex items-center justify-center shadow-xl transition-all ${isRecording ? 'bg-red-500 scale-110' : 'bg-[#128c7e]'}`}>
              <svg className="h-6 w-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" /></svg>
            </button>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/90 z-50 flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin" />
          <p className="devanagari font-bold text-[#128c7e]">सहेली आ रही है...</p>
        </div>
      )}
      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-10px); } }
        .animate-float { animation: float 6s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

