`;

const TOPICS = [
  { id: 'finance', name: 'पैसा और बैंक', desc: 'लोन और बचत का सही हिसाब', icon: '💰' },
  { id: 'packaging', name: 'पैकेजिंग और सजावट', desc: 'सामान को सुंदर बनाने के तरीके', icon: '📦' },
  { id: 'marketing', name: 'बिक्री और ग्राहक', desc: 'ज़्यादा सामान बेचने के तरीके', icon: '📢' },
  { id: 'schemes', name: 'सरकारी मदद', desc: 'सरकारी योजनाओं की पूरी जानकारी', icon: '🏛️' },
  { id: 'other', name: 'कुछ और पूछें', desc: 'कोई भी सवाल या सलाह', icon: '💬' },
];

const SAHELI_IMAGE = "https://image2url.com/r2/default/images/1769072984336-dcce0dca-5c10-4d48-aa6c-11e0ead8a24b.jpg";
const CDF_LOGO = "https://image2url.com/r2/default/images/1769073801640-26f71cc6-deb8-4340-afee-ef36d5b8f9c9.png";
const HELPLINE_NUMBER = "+91-9911988233";
const PROFILE_KEY = 'udyog_saheli_v9_no_db';

const INDIAN_STATES = [
  "आंध्र प्रदेश", "बिहार", "छत्तीसगढ़", "गुजरात", "हरियाणा", "झारखंड", 
  "मध्य प्रदेश", "महाराष्ट्र", "ओडिशा", "पंजाब", "राजस्थान", "उत्तर प्रदेश", "उत्तराखंड", "पश्चिम बंगाल"
];

const App: React.FC = () => {
  const [view, setView] = useState<'WELCOME' | 'ONBOARDING' | 'DASHBOARD' | 'CHAT' | 'FEEDBACK'>('WELCOME');
  const [onboardingStep, setOnboardingStep] = useState(0); 
  const [userProfile, setUserProfile] = useState<UserProfile>({ 
    name: '', mobile: '', village: '', state: '', onboarded: false 
  });
  const [selectedTopic, setSelectedTopic] = useState<typeof TOPICS[0] | null>(null);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [messages, setMessages] = useState<TranscriptionItem[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');
  const [chatInput, setChatInput] = useState('');

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const micProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const currentOutputTranscription = useRef<string>('');
  const currentGroundingLinks = useRef<GroundingLink[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem(PROFILE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      setUserProfile(parsed);
      if (parsed.onboarded) setView('DASHBOARD');
    }
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  const saveProfile = async (data: UserProfile) => {
    localStorage.setItem(PROFILE_KEY, JSON.stringify(data));
    setUserProfile(data);
    await dbService.syncProfile(data);
  };

  const handleLogout = (e: React.MouseEvent) => {
    e.preventDefault();
    if (window.confirm("क्या आप वाकई लॉगआउट करना चाहती हैं?")) {
      closeSession();
      localStorage.removeItem(PROFILE_KEY);
      setUserProfile({ name: '', mobile: '', village: '', state: '', onboarded: false });
      setMessages([]);
      setOnboardingStep(0);
      setView('WELCOME');
    }
  };

  const stopAudio = () => {
    sourcesRef.current.forEach(s => { try { s.stop(); s.disconnect(); } catch (e) {} });
    sourcesRef.current.clear();
    nextStartTimeRef.current = 0;
  };

  const stopRecordingInternal = () => {
    if (micProcessorRef.current) { micProcessorRef.current.disconnect(); micProcessorRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach(t => t.stop()); streamRef.current = null; }
    setIsRecording(false);
  };

  const initSession = async (customInstruction?: string) => {
    if (sessionRef.current) return sessionRef.current;
    setStatus(AppStatus.CONNECTING);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    if (!audioContextRef.current) {
      audioContextRef.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 })
      };
    }

    const dynamicInstruction = `${BASE_SYSTEM_INSTRUCTION}\nयूज़र: ${userProfile.name}, गाँव: ${userProfile.village}\n${customInstruction || ""}`;

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        systemInstruction: dynamicInstruction,
        outputAudioTranscription: {},
        tools: [{ googleSearch: {} }],
      },
      callbacks: {
        onopen: () => setStatus(AppStatus.LISTENING),
        onmessage: async (message: LiveServerMessage) => {
          // Handle Search Grounding
          const groundingMetadata = (message.serverContent as any)?.groundingMetadata;
          if (groundingMetadata?.groundingChunks) {
            groundingMetadata.groundingChunks.forEach((chunk: any) => {
              if (chunk.web) {
                currentGroundingLinks.current.push({
                  uri: chunk.web.uri,
                  title: chunk.web.title || 'अधिक जानकारी'
                });
              }
            });
          }

          if (message.serverContent?.outputTranscription) {
            currentOutputTranscription.current += message.serverContent.outputTranscription.text;
          }

          if (message.serverContent?.turnComplete) {
            const modelText = currentOutputTranscription.current.trim();
            if (modelText && view === 'CHAT') {
              const modelMsg: TranscriptionItem = { 
                text: modelText, 
                role: 'model', 
                timestamp: Date.now(),
                visual: currentGroundingLinks.current.length > 0 ? {
                  type: 'search',
                  groundingLinks: [...currentGroundingLinks.current]
                } : undefined
              };
              setMessages(prev => [...prev, modelMsg]);
              dbService.logInteraction(userProfile.mobile, modelMsg);
            }
            currentOutputTranscription.current = '';
            currentGroundingLinks.current = [];
          }

          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            setStatus(AppStatus.SPEAKING);
            const ctx = audioContextRef.current!.output;
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.addEventListener('ended', () => { 
              sourcesRef.current.delete(source); 
              if (sourcesRef.current.size === 0) setStatus(AppStatus.LISTENING); 
            });
            const startTime = Math.max(nextStartTimeRef.current, ctx.currentTime + 0.05); 
            source.start(startTime);
            nextStartTimeRef.current = startTime + audioBuffer.duration;
            sourcesRef.current.add(source);
          }
          if (message.serverContent?.interrupted) stopAudio();
        },
        onerror: () => setStatus(AppStatus.ERROR),
        onclose: () => setStatus(AppStatus.IDLE)
      }
    });
    sessionRef.current = await sessionPromise;
    return sessionRef.current;
  };

  const toggleRecording = async () => {
    if (!isRecording) {
      stopAudio();
      try {
        const session = await initSession(`विषय: ${selectedTopic?.name}`);
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        streamRef.current = stream;
        const source = audioContextRef.current!.input.createMediaStreamSource(stream);
        const scriptProcessor = audioContextRef.current!.input.createScriptProcessor(2048, 1, 1); 
        scriptProcessor.onaudioprocess = (e) => session?.sendRealtimeInput({ media: createBlob(e.inputBuffer.getChannelData(0)) });
        source.connect(scriptProcessor);
        scriptProcessor.connect(audioContextRef.current!.input.destination);
        micProcessorRef.current = scriptProcessor;
        setIsRecording(true);
      } catch (err) {
        setStatus(AppStatus.ERROR);
      }
    } else {
      stopRecordingInternal();
    }
  };

  const handleSendText = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!chatInput.trim()) return;

    stopAudio();
    const textToSend = chatInput;
    setChatInput('');
    const userMsg: TranscriptionItem = { text: textToSend, role: 'user', timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    dbService.logInteraction(userProfile.mobile, userMsg);

    try {
      const session = await initSession();
      session.sendRealtimeInput({ parts: [{ text: textToSend }] });
    } catch (err) {}
  };

  const closeSession = () => {
    if (sessionRef.current) { try { sessionRef.current.close(); } catch(e) {} sessionRef.current = null; }
    stopAudio();
    setStatus(AppStatus.IDLE);
  };

  const renderOnboarding = () => {
    if (onboardingStep === 0) {
      return (
        <div className="flex flex-col h-full bg-white p-6 animate-fade-in text-center">
          <div className="flex-1 flex flex-col justify-center space-y-6">
            <div className="text-6xl mb-4">⚠️</div>
            <div className="flex items-center justify-center space-x-2 text-red-600">
               <h2 className="text-2xl font-black devanagari">महत्वपूर्ण सूचना (Disclaimer)</h2>
            </div>
            <div className="space-y-4">
              <div className="bg-red-50 p-5 rounded-3xl border border-red-100 text-left shadow-inner">
                <p className="text-[17px] devanagari text-red-900 font-bold leading-relaxed">
                  दीदी, यह ऐप केवल जानकारी के लिए है। बड़ा बिज़नेस फैसला लेने से पहले विशेषज्ञों की सलाह ज़रूर लें।
                </p>
              </div>
            </div>
          </div>
          <button onClick={() => setOnboardingStep(1)} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl">
            मैं सहमत हूँ
          </button>
        </div>
      );
    }

    return (
      <div className="flex flex-col h-full bg-white p-6 animate-fade-in overflow-y-auto">
        <h2 className="text-center font-bold devanagari text-lg mb-8">आपकी जानकारी</h2>
        <div className="space-y-4 flex-1">
          <input type="text" placeholder="नाम" value={userProfile.name} onChange={e => setUserProfile({...userProfile, name: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
          <input type="tel" placeholder="मोबाइल नंबर" value={userProfile.mobile} onChange={e => setUserProfile({...userProfile, mobile: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
          <input type="text" placeholder="गाँव" value={userProfile.village} onChange={e => setUserProfile({...userProfile, village: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold" />
          <select value={userProfile.state} onChange={e => setUserProfile({...userProfile, state: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl border-2 border-transparent focus:border-[#128c7e] devanagari font-bold">
            <option value="">राज्य चुनें</option>
            {INDIAN_STATES.map(s => <option key={s} value={s}>{s}</option>)}
          </select>
        </div>
        <button onClick={() => { saveProfile({...userProfile, onboarded: true}); setView('DASHBOARD'); }} disabled={!userProfile.name || !userProfile.mobile} className="w-full py-5 rounded-3xl bg-[#128c7e] text-white font-bold text-xl devanagari shadow-xl disabled:bg-gray-200">शुरू करें</button>
      </div>
    );
  };

  const renderFeedback = () => (
    <div className="flex flex-col h-full bg-white animate-fade-in">
      <header className="bg-[#128c7e] text-white p-4 flex items-center justify-between shadow-md">
        <button onClick={() => setView('DASHBOARD')} className="p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" /></svg></button>
        <h2 className="text-xl font-bold devanagari">सुझाव दें</h2>
        <div className="w-10" />
      </header>
      <div className="flex-1 p-6 space-y-6 overflow-y-auto">
        <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} className="w-full h-48 p-4 rounded-2xl border-2 border-gray-100 focus:border-[#128c7e] devanagari text-lg" placeholder="यहाँ सुझाव लिखें..." />
      </div>
      <div className="p-6">
        <button onClick={() => { alert("धन्यवाद दीदी!"); setFeedbackText(''); setView('DASHBOARD'); }} className="w-full py-5 rounded-3xl font-bold text-xl devanagari bg-[#128c7e] text-white shadow-xl">सुझाव भेजें</button>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white relative overflow-hidden">
      {view === 'WELCOME' ? (
        <div className="flex flex-col h-full items-center justify-between p-8 bg-gradient-to-b from-green-50 to-white text-center">
          <div className="flex-1 flex flex-col items-center justify-center space-y-6">
            <img src={SAHELI_IMAGE} alt="Saheli Logo" className="w-64 h-64 object-contain rounded-3xl shadow-2xl animate-float" />
            <h1 className="text-4xl font-black text-green-900 devanagari">उद्योग सहेली</h1>
            <p className="text-lg text-green-700 font-bold devanagari">ग्रामीण उद्यमियों की डिजिटल साथी</p>
          </div>
          <div className="w-full flex flex-col items-center space-y-8">
            <button onClick={() => setView(userProfile.onboarded ? 'DASHBOARD' : 'ONBOARDING')} className="w-full max-w-xs bg-[#128c7e] text-white py-5 rounded-3xl font-bold text-xl devanagari shadow-xl">नमस्ते, शुरू करें</button>
            <div className="flex flex-col items-center space-y-2">
              <img src={CDF_LOGO} alt="CDF Logo" className="h-12 object-contain filter drop-shadow-lg" />
              <p className="text-[10px] text-green-800 devanagari font-black">Connecting Dreams Foundation</p>
            </div>
          </div>
        </div>
      ) : view === 'ONBOARDING' ? (
        renderOnboarding()
      ) : view === 'FEEDBACK' ? (
        renderFeedback()
      ) : view === 'DASHBOARD' ? (
        <div className="flex flex-col h-full bg-white">
          <header className="bg-[#128c7e] text-white px-4 py-5 flex flex-col shadow-lg z-20">
            <div className="flex justify-between items-center">
              <div className="flex items-center space-x-3">
                <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full border border-white/20" alt="Saheli" />
                <h1 className="text-lg font-bold devanagari">नमस्ते, {userProfile.name}</h1>
              </div>
              <div className="flex items-center space-x-2">
                <button onClick={() => setView('FEEDBACK')} className="bg-white/10 px-3 py-2 rounded-xl text-[10px] font-bold devanagari text-white">फीडबैक</button>
                <button onClick={handleLogout} className="bg-red-500/80 px-3 py-2 rounded-xl text-[10px] font-bold devanagari text-white">लॉगआउट</button>
              </div>
            </div>
          </header>
          <main className="flex-1 overflow-y-auto bg-gray-50/20 pb-6">
            <div className="p-5 bg-green-50/40 border-b border-gray-100 flex items-center space-x-3">
                <div className="w-10 h-10 bg-[#128c7e] rounded-xl flex items-center justify-center text-white text-xl font-black shadow-md">स</div>
                <div><h3 className="font-bold devanagari text-green-900">सहेली सलाहकार</h3><p className="text-[9px] text-green-700 font-bold uppercase tracking-widest">Digital Partner</p></div>
            </div>
            <div className="divide-y divide-gray-100 bg-white shadow-sm mb-6">
              {TOPICS.map((topic) => (
                <button key={topic.id} onClick={() => { setSelectedTopic(topic); setView('CHAT'); }} className="w-full flex items-center p-5 active:bg-gray-100 text-left">
                  <div className="w-14 h-14 rounded-2xl bg-gray-50 border border-gray-100 flex items-center justify-center text-3xl">{topic.icon}</div>
                  <div className="ml-5 flex-1"><h4 className="font-bold text-[17px] devanagari text-slate-800">{topic.name}</h4><p className="text-[13px] text-gray-400 devanagari mt-0.5">{topic.desc}</p></div>
                </button>
              ))}
            </div>
            <div className="mx-4 p-5 bg-[#128c7e]/5 rounded-3xl border border-[#128c7e]/10 flex flex-col items-center space-y-4 text-center">
              <h4 className="devanagari font-black text-[#128c7e] text-lg">हेल्पलाइन: {HELPLINE_NUMBER}</h4>
            </div>
            <div className="mt-8 flex flex-col items-center py-6">
              <img src={CDF_LOGO} className="h-10 opacity-60 mb-1" alt="CDF" />
              <p className="text-[10px] text-green-800 devanagari font-black">Connecting Dreams Foundation</p>
            </div>
          </main>
        </div>
      ) : (
        <div className="flex flex-col h-full whatsapp-bg">
          <header className="bg-[#128c7e] text-white px-4 py-3 flex items-center shadow-lg z-20">
            <button onClick={() => { closeSession(); setView('DASHBOARD'); setMessages([]); }} className="p-2 mr-1"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg></button>
            <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full mr-3" alt="Saheli" />
            <h1 className="text-[17px] font-bold devanagari">{selectedTopic?.name}</h1>
          </header>
          <main className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
            {messages.map((m, i) => (
              <div key={i} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${m.role === 'user' ? 'bubble-user rounded-tr-none' : 'bubble-saheli rounded-tl-none'}`}>
                  <p className="devanagari text-[17px] leading-[1.6] text-slate-800">{m.text}</p>
                  {m.visual?.groundingLinks && (
                    <div className="mt-3 pt-2 border-t border-gray-100">
                      <p className="text-[11px] font-bold text-gray-500 mb-2">स्त्रोत (Sources):</p>
                      <div className="space-y-1">
                        {m.visual.groundingLinks.map((link, idx) => (
                          <a key={idx} href={link.uri} target="_blank" rel="noopener noreferrer" className="block text-xs text-[#128c7e] underline truncate">
                            {link.title}
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}
            <div ref={chatEndRef} />
          </main>
          <footer className="bg-white p-2 flex items-end space-x-2 border-t border-gray-200 z-30">
            <form onSubmit={handleSendText} className="flex-1 bg-gray-100 rounded-3xl flex items-center px-4 py-1">
              <input type="text" value={chatInput} onChange={e => setChatInput(e.target.value)} placeholder="यहाँ लिखें..." className="flex-1 bg-transparent py-2 focus:outline-none devanagari" />
            </form>
            <div 
              onMouseDown={() => toggleRecording()} 
              onMouseUp={() => stopRecordingInternal()} 
              onTouchStart={() => toggleRecording()} 
              onTouchEnd={() => stopRecordingInternal()}
              className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-all ${isRecording ? 'bg-red-500 scale-110' : 'bg-[#128c7e]'}`}>
              <svg className="h-5 w-5 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" /></svg>
            </div>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 z-50 flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <p className="devanagari text-[#128c7e] font-bold">सहेली आ रही है...</p>
        </div>
      )}
      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-15px); } }
        .animate-float { animation: float 6s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

