            <button onClick={() => { closeSession(); setView('DASHBOARD'); setMessages([]); }} className="p-2 mr-1"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg></button>
            <img src={SAHELI_IMAGE} className="w-10 h-10 rounded-full mr-3" alt="Saheli" />
            <h1 className="text-[17px] font-bold devanagari">{selectedTopic?.name}</h1>
