            </button>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/90 z-50 flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <p className="devanagari text-[#128c7e] font-bold">कनेक्ट हो रहा है...</p>
        </div>
      )}
      <style>{`
