            <p className="devanagari text-xs text-gray-400 font-bold tracking-wide">
              {isRecording ? 'सहेली सुन रही है...' : 'बोलने के लिए दबाएं'}
            </p>
            <div 
              onMouseDown={() => toggleRecording()} 
              onMouseUp={() => stopRecordingInternal()} 
              onTouchStart={() => toggleRecording()} 
              onTouchEnd={() => stopRecordingInternal()}
              className={`w-16 h-16 rounded-full flex items-center justify-center shadow-xl transition-all active:scale-90 touch-none select-none cursor-pointer ${isRecording ? 'bg-red-500 ring-8 ring-red-100' : 'bg-[#128c7e] hover:bg-[#075e54]'}`}>
              <svg className="h-8 w-8 text-white" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" />
                <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
              </svg>
            </div>
          </footer>
        </div>
      )}
      {status === AppStatus.CONNECTING && (
        <div className="absolute inset-0 bg-white/95 z-50 flex flex-col items-center justify-center space-y-4">
          <div className="w-12 h-12 border-4 border-[#128c7e] border-t-transparent rounded-full animate-spin"></div>
          <p className="devanagari text-[#128c7e] font-bold">सहेली आ रही है...</p>
        </div>
      )}
      <style>{`
        @keyframes fade-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }
        @keyframes float { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-15px); } }
        .animate-float { animation: float 6s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { AppStatus, TranscriptionItem, UserProfile, GroundingLink } from './types';
import { decode, decodeAudioData, createBlob } from './services/audioUtils';
import { dbService } from './services/dbService';
import VoicePulse from './components/VoicePulse';

// STABLE LOW COST VERSION: Strictly enforces Devanagari Hindi to prevent Urdu/Roman script display
const BASE_SYSTEM_INSTRUCTION = `नाम: "उद्योग सहेली"। नियम: केवल और केवल देवनागरी हिंदी लिपि (Devanagari Hindi script) का उपयोग करें। किसी अन्य लिपि (जैसे उर्दू, अंग्रेजी, रोमन) का प्रयोग पूर्णतः वर्जित है। यूज़र की आवाज़ को केवल हिंदी देवनागरी में ही समझें और डिस्प्ले करें। "दीदी" बोलें। उत्तर बहुत छोटे और सटीक दें। Google Search सिर्फ बाज़ार भाव या सरकारी योजनाओं के लिए ही करें।`;

const TOPICS = [
